function formatChatTime(ts: number): string | null {
  if (!Number.isFinite(ts) || ts <= 0) return null
  const ms = ts < 1_000_000_000_000 ? ts * 1000 : ts
  const d = new Date(ms)
  if (Number.isNaN(d.getTime())) return null
  const hh = String(d.getHours()).padStart(2, '0')
  const mm = String(d.getMinutes()).padStart(2, '0')
  return `${hh}:${mm}`
}

function formatChatSpeakerLabel(msg: ChatTranscriptEntry, keeperName: string, autonomousSummary: string | null, memoryOnly: boolean): string {
  if (msg.role === 'user') {
    const actor = msg.speakerName ?? msg.speakerId ?? null
    if (msg.speakerAuthority === 'keeper') {
      return `Keeper · ${actor ?? 'keeper'}`
    }
    if (msg.speakerAuthority === 'external') {
      return actor ? `${actor} (외부)` : '외부 발신자'
    }
    if (msg.speakerAuthority === 'owner') {
      return actor && actor.toLowerCase() !== 'operator' ? `Operator (${actor})` : 'Operator'
    }
    return actor ?? msg.speakerLabel ?? '사용자'
  }
  if (autonomousSummary !== null) return `${keeperName} · Autonomous Turn`
  if (memoryOnly) return `${keeperName} · Memory Recall`
  if (msg.toolName) return `Tool · ${msg.toolName}`
  return keeperName
}

function deliveryBadgeTone(state: ChatDeliveryState | undefined): 'ok' | 'warn' | 'bad' | 'info' | 'brass' | undefined {
  switch (state) {
    case 'Queued':
    case 'Pending_processing':
      return 'warn'
    case 'Sending':
    case 'Confirming_delivery':
      return 'info'
    case 'Streaming':
      return 'brass'
    case 'Delivered':
    case 'Cut_recovered':
      return 'ok'
    case 'Failed':
      return 'bad'
    default:
      return undefined
  }
}

const MAX_TOOL_RESULT_CACHE = 50
const MAX_AUTO_HYDRATE_TOOL_RESULTS = 8
const MAX_OBSERVER_SEEN_SEQS = 4096
const MAX_OBSERVER_STREAMS = 100
const MAX_LOCAL_OWNED_OPS = 200

interface ObserverOperationStream {
  readonly operationId: string
  executionId: string
  readonly assistantId: string
  dispatcher: ChatStreamFrameDispatcher | null
  readonly seenSeqs: Set<number>
  evictedSeqWatermark: number
  entryCreated: boolean
  terminal: boolean
  completedAtHistorySeq: number | null
  shadowed: boolean
}

function isRecordLike(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function nonBlankStr(value: unknown): string | null {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : null
}

function recordObserverSeq(stream: ObserverOperationStream, seq: number): boolean {
  if (seq <= stream.evictedSeqWatermark || stream.seenSeqs.has(seq)) return false
  stream.seenSeqs.add(seq)
  while (stream.seenSeqs.size > MAX_OBSERVER_SEEN_SEQS) {
    const oldest = stream.seenSeqs.values().next().value
    if (oldest === undefined) break
    stream.seenSeqs.delete(oldest)
    if (oldest > stream.evictedSeqWatermark) stream.evictedSeqWatermark = oldest
  }
  return true
}

function addBoundedOpId(set: Set<string>, id: string, maxSize: number): void {
  if (set.has(id)) {
    set.delete(id)
  }
  set.add(id)
  while (set.size > maxSize) {
    const oldest = set.values().next().value
    if (oldest === undefined) break
    set.delete(oldest)
  }
}

function setBoundedObserverStream(
  map: Map<string, ObserverOperationStream>,
  operationId: string,
  stream: ObserverOperationStream,
): void {
  map.set(operationId, stream)
  while (map.size > MAX_OBSERVER_STREAMS) {
    let evictKey: string | undefined
    for (const [key, candidate] of map) {
      if (key !== operationId && (candidate.terminal || candidate.shadowed)) {
        evictKey = key
        break
      }
    }
    if (evictKey === undefined) {
      for (const key of map.keys()) {
        if (key !== operationId) {
          evictKey = key
          break
        }
      }
    }
    if (evictKey === undefined) break
    map.delete(evictKey)
  }
}

function isOperationSettledInEntries(
  entries: readonly ChatTranscriptEntry[],
  operationId: string,
): boolean {
  if (hasSettledOperation(entries, operationId)) return true
  return entries.some(
    (entry) =>
      entry.role === 'assistant'
      && (entry.operationId === operationId || entry.replyOperationId === operationId)
      && (entry.deliveryState === 'Delivered' || entry.deliveryState === 'Cut_recovered'),
  )
}

function entryDisplayAttachments(msg: ChatTranscriptEntry): readonly AttachmentRef[] {
  const fromCanonical = msg.attachments ?? []
  const fromLegacy = (msg.retainedImages ?? [])
    .map((img) => decodeAttachmentRef({ t: 'image', src: img.path, cap: img.caption }))
    .filter((ref): ref is AttachmentRef => ref !== null)
  if (fromCanonical.length === 0) return fromLegacy
  if (fromLegacy.length === 0) return fromCanonical
  return dedupeAttachments([...fromCanonical, ...fromLegacy])
}

function joinThinkingMap(map: Map<string, string>): string | undefined {
  const ordered = Array.from(map.values()).filter((v) => v.length > 0)
  return ordered.length > 0 ? ordered.join('\n\n') : undefined
}

function setBoundedToolResultCache(
  prev: Record<string, ToolResultState>,
  key: string,
  entry: ToolResultState,
): Record<string, ToolResultState> {
  const next: Record<string, ToolResultState> = { ...prev }
  delete next[key]
  next[key] = entry
  const keys = Object.keys(next)
  while (keys.length > MAX_TOOL_RESULT_CACHE) {
    const oldest = keys.shift()
    if (oldest) delete next[oldest]
  }
  return next
}

export function KeeperChatTab(props: KeeperChatTabProps) {
  const { keeper } = props
  const [messagesState, setMessagesState] = useState<KeeperMessagesState>(() => ({
    keeperName: keeper.name,
    entries: [],
  }))
  const messagesStateRef = useRef<KeeperMessagesState>(messagesState)
  messagesStateRef.current = messagesState
  const isSwitchingKeeper = messagesState.keeperName !== keeper.name
  const scopedMessages = isSwitchingKeeper ? [] : messagesState.entries
  const [nextCursor, setNextCursor] = useState<string | null>(null)
  const [hasMore, setHasMore] = useState(false)
  const [loadingHistory, setLoadingHistory] = useState(true)
  const [historyError, setHistoryError] = useState<string | null>(null)

  const [queueRead, setQueueRead] = useState<QueueRead | null>(null)
  const queue = queueRead?.keeperName === keeper.name && isEpochCurrent(queueRead.epoch)
    ? queueRead
    : null
  const queuedOps = queue?.operations ?? []
  const [draft, setDraftState] = useState('')
  const draftRef = useRef('')
  const setDraft = useCallback((next: string | ((cur: string) => string)) => {
    setDraftState((cur) => {
      const resolved = typeof next === 'function' ? next(cur) : next
      draftRef.current = resolved
      return resolved
    })
  }, [])
  const [discordReplyId, setDiscordReplyId] = useState<string | null>(null)
  const discordReplyTrigger = useRef<HTMLButtonElement | null>(null)
  const discordSession = authSession.value
  const discordEpoch = sessionEpoch.value
  const canAdminLocalChat = canUseSingleUserTokenAdmin(discordSession)
  const [discordAuthority, setDiscordAuthority] = useState<(DiscordReplyAuthority & { epoch: number }) | null>(null)
  const hasDiscordReplySource = scopedMessages.some(msg => msg.discordReplyOrigin)
  const hasBearer = discordSession.kind === 'single_user_local' && canAdminLocalChat && discordSession.tokenPresent
  const discordOperator = hasBearer && discordAuthority?.epoch === discordEpoch ? discordAuthority : null
  useEffect(() => {
    if (!hasBearer || !hasDiscordReplySource) return
    let live = true
    void readDiscordOperator().then(authority => {
      if (authority && live && isEpochCurrent(discordEpoch)) {
        setDiscordAuthority({ ...authority, epoch: discordEpoch })
      }
    })
    return () => { live = false }
  }, [discordEpoch, hasBearer, hasDiscordReplySource])
  const [composerAttachments, setComposerAttachmentsState] = useState<readonly ComposerAttachmentItem[]>([])
  const composerAttachmentsRef = useRef<readonly ComposerAttachmentItem[]>([])
  const setComposerAttachments = useCallback(
    (next: readonly ComposerAttachmentItem[] | ((cur: readonly ComposerAttachmentItem[]) => readonly ComposerAttachmentItem[])) => {
      setComposerAttachmentsState((cur) => {
        const resolved = typeof next === 'function' ? next(cur) : next
        composerAttachmentsRef.current = resolved
        return resolved
      })
    },
    [],
  )
  const clearComposerAttachments = useCallback(() => {
    revokeComposerPreviews(composerAttachmentsRef.current)
    composerAttachmentsRef.current = []
    setComposerAttachmentsState([])
  }, [])
  useEffect(() => () => revokeComposerPreviews(composerAttachmentsRef.current), [])
  const [sending, setSending] = useState(false)
  const [followUpSubmitting, setFollowUpSubmitting] = useState(false)
  const [voiceBusy, setVoiceBusy] = useState(false)
  const [controlToken, setControlToken] = useState<string | null>(keeper.chat_control_token)
  const [companionOpen, setCompanionOpen] = useState(false)
  const [blockPrefs, setBlockPrefs] = useState<ChatBlockPrefs>(() => loadChatBlockPrefs())

  const updateBlockPrefs = useCallback((updater: (cur: ChatBlockPrefs) => ChatBlockPrefs) => {
    const cur = blockPrefsRef.current
    const next = updater(cur)
    blockPrefsRef.current = next
    saveChatBlockPrefs(next)
    setBlockPrefs(next)
    if (next.tools !== cur.tools) {
      autoOpenedGroupsRef.current.clear()
      expandedCardKeysRef.current = {}
      renderedOpenRef.current.clear()
      setExpandedCardKeys({})
    }
    if (next.thinking !== cur.thinking) {
      setExpandedThinkingKeys({})
    }
  }, [])

  const [btw, setBtw] = useState<BtwQueryState>({
    status: 'idle',
    prompt: '',
    reply: '',
    error: null,
  })
  const [btwOpen, setBtwOpen] = useState(false)
  const [btwInput, setBtwInput] = useState('')
  const [renderWindow, setRenderWindow] = useState(INITIAL_RENDER_WINDOW)
  const [isNearBottom, setIsNearBottom] = useState(true)
  const [unseenBelowCount, setUnseenBelowCount] = useState(0)
  const [toolResultCache, setToolResultCache] = useState<Record<string, ToolResultState>>({})
  const [expandedCardKeys, setExpandedCardKeys] = useState<Record<string, boolean>>({})
  const [expandedThinkingKeys, setExpandedThinkingKeys] = useState<Record<string, boolean>>({})
  const [expandedPreKeys, setExpandedPreKeys] = useState<Record<string, boolean>>({})
  const [copiedPreKey, setCopiedPreKey] = useState<string | null>(null)
  const [waitingInventory, setWaitingInventory] = useState<KeeperWaitingInventoryData | null>(null)
  const [turnPreviews, setTurnPreviews] = useState<readonly ReceivedTurnPreview[]>([])
  const [invalidatedSnapshot, setInvalidatedSnapshot] = useState<TurnSnapshot | undefined>()
  const [lastWorked, setLastWorked] = useState<Extract<KeeperObserverChatSignal, { kind: 'turn_succeeded' }> | null>(null)

  const chatListRef = useRef<HTMLDivElement>(null)
  const chatFeedRef = useRef<HTMLDivElement>(null)
  const composerRef = useRef<HTMLTextAreaElement>(null)
  const openAttachmentPickerRef = useRef<(() => void) | null>(null)
  const voiceInputRef = useRef<HTMLInputElement>(null)
  const streamAbortRef = useRef<AbortController | null>(null)
  const btwAbortRef = useRef<AbortController | null>(null)
  const sendingRef = useRef(false)
  const followUpSubmittingRef = useRef(false)
  const streamRunIdRef = useRef(0)
  const sendingOperationRef = useRef<{ operationId: string; executionId: string } | null>(null)
  const observerStreamsRef = useRef<Map<string, ObserverOperationStream>>(new Map())
  const localOwnedOpIdsRef = useRef<Set<string>>(new Set())
  const refreshChatRef = useRef<(...reads: ChatRead[]) => void>(() => {})
  const retryQueueRef = useRef<() => void>(() => {})
  const stickToBottomRef = useRef(true)
  const forceScrollBottomRef = useRef(true)
  const pendingPrependAnchorRef = useRef<{ readonly prevScrollHeight: number; readonly prevScrollTop: number } | null>(null)
  const prevTailSigRef = useRef('')
  const mountedRef = useRef(true)
  const activeKeeperRef = useRef(keeper.name)
  const turnRead = props.turnSnapshot
  const turnReadRef = useRef(turnRead)
  turnReadRef.current = turnRead
  const lastTurn = useRef<{
    readonly keeper: string
    readonly epoch: number
    readonly active: KeeperActiveTurn | null
    readonly updatedAt: number
    readonly retiredOwners: Set<string>
  } | null>(null)
  const row = turnRead?.kind === 'value' ? turnRead.data.get(keeper.name) : undefined
  let snapshot = lastTurn.current?.keeper === keeper.name && isEpochCurrent(lastTurn.current.epoch)
    ? lastTurn.current : null
  if (turnRead?.kind === 'value' && row?.status === 'ok' && (!turnRead.stale || !snapshot)) {
    const retiredOwners = snapshot?.retiredOwners ?? new Set<string>()
    const previousOwner = snapshot?.active?.owner_key
    const observedOwner = row.active?.owner_key
    // An idle or replacement receipt can end an owner before its first
    // preview arrives. A preview for another owner may still be ahead of HTTP.
    if (!turnRead.stale && previousOwner
        && (row.active === null || (observedOwner && observedOwner !== previousOwner))) {
      retiredOwners.add(previousOwner)
    }
    snapshot = {
      keeper: keeper.name, epoch: currentSessionEpoch(),
      active: row.active, updatedAt: turnRead.updatedAt, retiredOwners,
    }
    lastTurn.current = snapshot
  }
  const activeTurn = turnRead ? snapshot?.active ?? null : keeper.active_turn
  const turnOwnerRef = useRef(activeTurn?.owner_key)
  turnOwnerRef.current = activeTurn?.owner_key
  const invalidateTurn = useCallback(() => {
    setInvalidatedSnapshot(turnReadRef.current)
    setTurnPreviews((previous) => previous.some((sample) => sample.live)
      ? previous.map((sample) => ({ ...sample, live: false }))
      : previous)
  }, [])
  useLayoutEffect(() => {
    if (turnRead?.kind === 'failed' || turnRead?.kind === 'absent'
      || (turnRead?.kind === 'value' && row?.status !== 'ok')) invalidateTurn()
  }, [turnRead, row, invalidateTurn])
  const hasLoadedEarlierRef = useRef(false)
  const earlierAbortRef = useRef<AbortController | null>(null)
  const earlierGenRef = useRef(0)
  const requestedExecIdsRef = useRef<Set<string>>(new Set())
  const toolFetchControllersRef = useRef<Map<string, AbortController>>(new Map())
  const toolResultCacheRef = useRef<Record<string, ToolResultState>>(toolResultCache)
  toolResultCacheRef.current = toolResultCache
  const expandedCardKeysRef = useRef<Record<string, boolean>>(expandedCardKeys)
  expandedCardKeysRef.current = expandedCardKeys
  const blockPrefsRef = useRef<ChatBlockPrefs>(blockPrefs)
  blockPrefsRef.current = blockPrefs
  const autoOpenedGroupsRef = useRef<Set<string>>(new Set())
  const renderedOpenRef = useRef<Map<string, boolean>>(new Map())
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // NOTE: Intentionally keep evicted keys in `requestedExecIdsRef` so auto-hydration
  // never thrash-fetches in an infinite loop when >MAX_TOOL_RESULT_CACHE cards stay open.
  // Explicit user clicks ("실행 결과 불러오기") and manual re-toggles pass `force = true`.
  const updateToolResultCache = useCallback((key: string, entry: ToolResultState) => {
    toolResultCacheRef.current = setBoundedToolResultCache(toolResultCacheRef.current, key, entry)
    setToolResultCache((prev) => {
      const next = setBoundedToolResultCache(prev, key, entry)
      toolResultCacheRef.current = next
      return next
    })
  }, [])

  const resetToolResultCache = useCallback(() => {
    toolResultCacheRef.current = {}
    setToolResultCache({})
  }, [])

  const resetExpandUiState = useCallback(() => {
    autoOpenedGroupsRef.current.clear()
    renderedOpenRef.current.clear()
    expandedCardKeysRef.current = {}
    setExpandedCardKeys({})
    setExpandedThinkingKeys({})
    setExpandedPreKeys({})
    setCopiedPreKey(null)
    if (copyTimerRef.current) {
      clearTimeout(copyTimerRef.current)
      copyTimerRef.current = null
    }
  }, [])

  const setCardExpanded = useCallback((cardKey: string, open: boolean, executionId?: string) => {
    const trimmedExec = executionId?.trim() || ''
    const execKey = trimmedExec ? `exec:${trimmedExec}` : ''
    const curRef = expandedCardKeysRef.current
    if (curRef[cardKey] !== open || (execKey && curRef[execKey] !== open)) {
      const syncNext: Record<string, boolean> = { ...curRef, [cardKey]: open }
      if (execKey) syncNext[execKey] = open
      expandedCardKeysRef.current = syncNext
    }
    setExpandedCardKeys((prev) => {
      if (prev[cardKey] === open && (!execKey || prev[execKey] === open)) {
        return prev
      }
      const next: Record<string, boolean> = { ...prev, [cardKey]: open }
      if (execKey) next[execKey] = open
      expandedCardKeysRef.current = next
      return next
    })
  }, [])

  const handleCopyPre = useCallback(async (preKey: string, text: string) => {
    const ok = await copyTextToClipboard(text)
    if (!ok || !mountedRef.current) return
    setCopiedPreKey(preKey)
    if (copyTimerRef.current) clearTimeout(copyTimerRef.current)
    copyTimerRef.current = setTimeout(() => {
      copyTimerRef.current = null
      if (mountedRef.current) setCopiedPreKey(null)
    }, 1500)
  }, [])

  const scrollToBottom = useCallback((behavior: ScrollBehavior = 'auto') => {
    const el = chatListRef.current
    if (!el) return
    stickToBottomRef.current = true
    setIsNearBottom(true)
    setUnseenBelowCount(0)
    if (behavior === 'auto' || typeof el.scrollTo !== 'function') {
      el.scrollTop = el.scrollHeight
    } else {
      el.scrollTo({ top: el.scrollHeight, behavior })
    }
  }, [])

  useEffect(() => {
    const feed = chatFeedRef.current
    if (!feed || typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(() => {
      if (stickToBottomRef.current) scrollToBottom()
    })
    observer.observe(feed)
    return () => observer.disconnect()
  }, [scrollToBottom])

  const handleChatScroll = useCallback(() => {
    const el = chatListRef.current
    if (!el) return
    const distanceFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight
    const near = distanceFromBottom <= BOTTOM_STICKY_THRESHOLD_PX
    stickToBottomRef.current = near
    setIsNearBottom(near)
    if (near) setUnseenBelowCount(0)
  }, [])

  const abortAllToolFetches = useCallback(() => {
    for (const ctrl of toolFetchControllersRef.current.values()) {
      ctrl.abort()
    }
    toolFetchControllersRef.current.clear()
  }, [])

  const invalidateEarlierReads = useCallback(() => {
    earlierGenRef.current += 1
    earlierAbortRef.current?.abort()
    earlierAbortRef.current = null
  }, [])

  useEffect(() => {
    mountedRef.current = true
    return () => {
      mountedRef.current = false
      invalidateEarlierReads()
      abortAllToolFetches()
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current)
        copyTimerRef.current = null
      }
    }
  }, [abortAllToolFetches, invalidateEarlierReads])

  useEffect(() => {
    const switchedKeeper = activeKeeperRef.current !== keeper.name
    activeKeeperRef.current = keeper.name
    stickToBottomRef.current = true
    forceScrollBottomRef.current = true
    pendingPrependAnchorRef.current = null
    setRenderWindow(INITIAL_RENDER_WINDOW)
    setIsNearBottom(true)
    setUnseenBelowCount(0)
    hasLoadedEarlierRef.current = false
    invalidateEarlierReads()
    abortAllToolFetches()
    requestedExecIdsRef.current.clear()
    resetToolResultCache()
    resetExpandUiState()
    setWaitingInventory(null)
    setTurnPreviews([])
    setInvalidatedSnapshot(undefined)
    setLastWorked(null)
    if (switchedKeeper) {
      setMessagesState({ keeperName: keeper.name, entries: [] })
      setHasMore(false)
      setNextCursor(null)
      setQueueRead(null)
    }
  }, [keeper.name, abortAllToolFetches, invalidateEarlierReads, resetToolResultCache, resetExpandUiState])

  useEffect(() => {
    let lastEpoch = currentSessionEpoch()
    return sessionEpoch.subscribe((ep) => {
      if (ep !== lastEpoch) {
        lastEpoch = ep
        hasLoadedEarlierRef.current = false
        invalidateEarlierReads()
        streamAbortRef.current?.abort('session_epoch_changed')
        btwAbortRef.current?.abort('session_epoch_changed')
        abortAllToolFetches()
        requestedExecIdsRef.current.clear()
        resetToolResultCache()
        resetExpandUiState()
      }
    })
  }, [abortAllToolFetches, invalidateEarlierReads, resetToolResultCache, resetExpandUiState])

  useEffect(() => {
    if (!canAdminLocalChat) {
      abortAllToolFetches()
      requestedExecIdsRef.current.clear()
      resetToolResultCache()
    }
  }, [canAdminLocalChat, abortAllToolFetches, resetToolResultCache])

  const requestToolResult = useCallback(async (executionId: string, force = false) => {
    if (!canUseSingleUserTokenAdmin(authSession.peek())) return
    const trimmed = executionId.trim()
    if (!trimmed) return
    if (!force && (requestedExecIdsRef.current.has(trimmed) || toolFetchControllersRef.current.has(trimmed))) {
      return
    }
    if (force) {
      toolFetchControllersRef.current.get(trimmed)?.abort()
      toolFetchControllersRef.current.delete(trimmed)
    }
    requestedExecIdsRef.current.add(trimmed)
    const targetKeeper = keeper.name
    const startEpoch = currentSessionEpoch()
    const ctrl = new AbortController()
    toolFetchControllersRef.current.set(trimmed, ctrl)
    updateToolResultCache(trimmed, { status: 'loading' })
    try {
      const res = await fetchKeeperToolResultApi(targetKeeper, trimmed, TOOL_RESULT_PAGE_BYTES, ctrl.signal)
      if (
        !mountedRef.current
        || activeKeeperRef.current !== targetKeeper
        || !isEpochCurrent(startEpoch)
        || !canUseSingleUserTokenAdmin(authSession.peek())
        || toolFetchControllersRef.current.get(trimmed) !== ctrl
        || ctrl.signal.aborted
      ) {
        if (toolFetchControllersRef.current.get(trimmed) === ctrl) {
          requestedExecIdsRef.current.delete(trimmed)
        }
        return
      }
      if (!res.ok) {
        requestedExecIdsRef.current.delete(trimmed)
        if (res.error.kind === 'epoch_stale' || res.error.kind === 'aborted') return
        updateToolResultCache(trimmed, applyToolResultError(undefined, res.error))
        return
      }
      const payload = res.value
      if (payload.state === 'pending') {
        requestedExecIdsRef.current.delete(trimmed)
      }
      updateToolResultCache(trimmed, applyToolResultPage(undefined, payload))
    } finally {
      if (toolFetchControllersRef.current.get(trimmed) === ctrl) {
        toolFetchControllersRef.current.delete(trimmed)
      }
    }
  }, [keeper.name, updateToolResultCache])

  const loadMoreToolResult = useCallback(async (executionId: string, maxPages: number) => {
    if (!canUseSingleUserTokenAdmin(authSession.peek())) return
    const trimmed = executionId.trim()
    if (!trimmed) return
    if (toolFetchControllersRef.current.has(trimmed)) return
    const current = toolResultCacheRef.current[trimmed]
    if (!current || current.status !== 'loaded' || current.eof || current.isBinary) return
    const targetKeeper = keeper.name
    const startEpoch = currentSessionEpoch()
    const ctrl = new AbortController()
    toolFetchControllersRef.current.set(trimmed, ctrl)
    const isCurrent = () =>
      mountedRef.current
      && activeKeeperRef.current === targetKeeper
      && isEpochCurrent(startEpoch)
      && canUseSingleUserTokenAdmin(authSession.peek())
      && toolFetchControllersRef.current.get(trimmed) === ctrl
      && !ctrl.signal.aborted
    try {
      await fetchToolResultContinuation({
        keeperName: targetKeeper,
        executionId: trimmed,
        initialState: current,
        maxPages,
        signal: ctrl.signal,
        isCurrent,
        onUpdate: (next) => {
          if (isCurrent()) updateToolResultCache(trimmed, next)
        },
      })
    } finally {
      if (toolFetchControllersRef.current.get(trimmed) === ctrl) {
        toolFetchControllersRef.current.delete(trimmed)
      }
    }
  }, [keeper.name, updateToolResultCache])

  useEffect(() => {
    setControlToken(keeper.chat_control_token)
  }, [keeper.chat_control_token])

  const updateEntryById = useCallback((
    entryId: string,
    updater: (cur: ChatTranscriptEntry) => ChatTranscriptEntry,
  ) => {
    const ownerKeeper = keeper.name
    setMessagesState((prev) => {
      if (prev.keeperName !== ownerKeeper) return prev
      if (!prev.entries.some((m) => m.id === entryId)) return prev
      return {
        keeperName: prev.keeperName,
        entries: prev.entries.map((m) => (m.id === entryId ? updater(m) : m)),
      }
    })
  }, [keeper.name])

  const updateAssistantEntry = updateEntryById

  const recordLocalOwnedOp = useCallback((id: string) => {
    addBoundedOpId(localOwnedOpIdsRef.current, id, MAX_LOCAL_OWNED_OPS)
  }, [])

  const shadowObserverStreamsForExecution = useCallback((
    executionId: string,
    exceptOperationId?: string,
  ) => {
    const ownerKeeper = keeper.name
    const removedAssistantIds: string[] = []
    for (const stream of observerStreamsRef.current.values()) {
      if (stream.operationId === exceptOperationId || stream.shadowed) continue
      if (stream.operationId === executionId || stream.executionId === executionId) {
        stream.shadowed = true
        stream.terminal = true
        if (stream.entryCreated) removedAssistantIds.push(stream.assistantId)
      }
    }
    if (removedAssistantIds.length > 0) {
      const removedSet = new Set(removedAssistantIds)
      setMessagesState((prev) => {
        if (prev.keeperName !== ownerKeeper) return prev
        if (!prev.entries.some((m) => removedSet.has(m.id))) return prev
        return {
          keeperName: prev.keeperName,
          entries: prev.entries.filter((m) => !removedSet.has(m.id)),
        }
      })
    }
  }, [keeper.name])

  const createAssistantStreamCallbacks = useCallback((opts: {
    readonly assistantId: string
    readonly userId: string
    readonly initialAcceptedByServer: boolean
    readonly updateAssistant: (
      updater: (cur: ChatTranscriptEntry) => ChatTranscriptEntry,
      initialDelivery?: ChatDeliveryState,
    ) => void
    readonly updateExistingAssistant: (
      updater: (cur: ChatTranscriptEntry) => ChatTranscriptEntry,
    ) => void
    readonly onBatchBound?: (memberId: string, executionId: string) => void
    readonly onServerAccepted?: () => void
  }): StreamKeeperChatCallbacks => {
    const { assistantId, userId, updateAssistant, updateExistingAssistant } = opts
    let acceptedByServer = opts.initialAcceptedByServer
    const thinkingByBlock = new Map<string, string>()
    let liveTools: readonly ChatToolBlock[] = []
    const promoteStreaming = (cur: ChatDeliveryState | undefined): ChatDeliveryState =>
      cur === 'Failed' || cur === 'Delivered' ? cur : 'Streaming'
    const markUserDelivered = () => {
      acceptedByServer = true
      opts.onServerAccepted?.()
      updateEntryById(userId, (m) =>
        m.deliveryState === 'Delivered' ? m : { ...m, deliveryState: 'Delivered' },
      )
    }

    return {
      onBatchBound: opts.onBatchBound,
      onAccepted: (info) => {
        acceptedByServer = true
        opts.onServerAccepted?.()
        if (info.controlToken) setControlToken(info.controlToken)
        const accepted = acceptedReplyState(info.state)
        const interruptProblem = info.interruptProblem
        updateEntryById(userId, (m) => ({
          ...m,
          deliveryState: info.state === 'Queued' ? 'Queued' : 'Delivered',
        }))
        updateExistingAssistant((m) => ({
          ...m,
          deliveryState: accepted.delivery,
          errorDetail: accepted.detail ?? m.errorDetail,
          streamNotices: interruptProblem === null
            ? m.streamNotices
            : appendStreamNotice(m.streamNotices, { kind: 'interrupt', text: interruptProblem }),
        }))
      },
      onRunStarted: () => {
        markUserDelivered()
        updateAssistant((m) => ({ ...m, deliveryState: 'Pending_processing' }), 'Pending_processing')
      },
      onAttemptStarted: (attempt) => {
        markUserDelivered()
        thinkingByBlock.clear()
        liveTools = []
        updateAssistant((m) => ({
          ...m,
          content: '',
          thinking: undefined,
          toolCalls: undefined,
          attachments: undefined,
          retainedImages: undefined,
          providerRetry: undefined,
          runtimeAttempt: attempt ?? m.runtimeAttempt,
          deliveryState: 'Streaming',
        }), 'Streaming')
      },
      onProviderRetry: (retry) => {
        const projected = chatProviderRetry(retry)
        updateAssistant((m) => (m.content === ''
          ? { ...m, providerRetry: projected, deliveryState: promoteStreaming(m.deliveryState) }
          : m), 'Streaming')
      },
      onStreamProtocolError: ({ message, quarantinedStreamKey }) => {
        if (quarantinedStreamKey !== undefined) {
          liveTools = liveTools.map((tc) => (tc.streamKey === quarantinedStreamKey
            ? { ...tc, status: 'error' }
            : tc))
        }
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: quarantinedStreamKey === undefined ? m.toolCalls : snapshotTools,
          streamNotices: appendStreamNotice(m.streamNotices, { kind: 'protocol_error', text: message }),
        }), 'Streaming')
      },
      onContinuationCheckpoint: (message) => {
        updateAssistant((m) => ({
          ...m,
          streamNotices: appendStreamNotice(m.streamNotices, {
            kind: 'checkpoint',
            text: message ?? '턴이 체크포인트에서 멈췄고 이어서 진행해요.',
          }),
        }), 'Streaming')
      },
      onModelActivity: () => {
        markUserDelivered()
        updateAssistant((m) => ({
          ...m,
          deliveryState: promoteStreaming(m.deliveryState),
        }), 'Streaming')
      },
      onTextDelta: (delta) => {
        markUserDelivered()
        updateAssistant((m) => ({
          ...m,
          content: m.content + delta,
          providerRetry: undefined,
          deliveryState: 'Streaming',
        }), 'Streaming')
      },
      onThinkingDelta: (delta, blockKey = '0:0:0') => {
        markUserDelivered()
        thinkingByBlock.set(blockKey, (thinkingByBlock.get(blockKey) ?? '') + delta)
        const combined = joinThinkingMap(thinkingByBlock)
        updateAssistant((m) => ({
          ...m,
          thinking: combined,
          deliveryState: promoteStreaming(m.deliveryState),
        }), 'Streaming')
      },
      onAttachment: (event) => {
        markUserDelivered()
        if (event.role === 'user') {
          updateEntryById(userId, (m) => ({
            ...m,
            attachments: dedupeAttachments([...(m.attachments ?? []), event.attachment]),
          }))
          return
        }
        if (event.toolCallId) {
          liveTools = upsertStreamToolCall(
            liveTools,
            { toolCallId: event.toolCallId },
            (cur) => ({
              ...cur,
              attachments: dedupeAttachments([...(cur.attachments ?? []), event.attachment]),
            }),
          )
        }
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          attachments: dedupeAttachments([...(m.attachments ?? []), event.attachment]),
          toolCalls: event.toolCallId && snapshotTools.length > 0 ? snapshotTools : m.toolCalls,
          deliveryState: promoteStreaming(m.deliveryState),
        }), 'Streaming')
      },
      onRetainedImages: (retainedImages) => {
        if (retainedImages.length > 0) markUserDelivered()
        updateAssistant((m) => ({
          ...m,
          retainedImages,
          deliveryState: retainedImages.length > 0 ? promoteStreaming(m.deliveryState) : m.deliveryState,
        }), 'Streaming')
      },
      onThinkingSnapshot: (snapshot, blockKey = '0:0:0') => {
        markUserDelivered()
        thinkingByBlock.set(blockKey, snapshot)
        const combined = joinThinkingMap(thinkingByBlock)
        updateAssistant((m) => ({
          ...m,
          thinking: combined,
          deliveryState: promoteStreaming(m.deliveryState),
        }), 'Streaming')
      },
      onToolStart: (toolName, toolCallId, streamKey) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({
            ...cur,
            id: toolCallId ?? cur.id,
            streamKey: cur.streamKey ?? streamKey,
            name: toolName || cur.name,
            status: 'running',
          }),
          () => ({
            id: toolCallId,
            streamKey,
            name: toolName,
            status: 'running',
          }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          deliveryState: promoteStreaming(m.deliveryState),
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolAdmitted: (toolName, toolCallId, streamKey) => {
        const prevIdx = findToolCallIndex(liveTools, { toolCallId, streamKey })
        const prevStreamKey = prevIdx >= 0 ? liveTools[prevIdx]!.streamKey : undefined
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({
            ...cur,
            id: toolCallId ?? cur.id,
            streamKey: cur.streamKey ?? streamKey,
            name: toolName,
          }),
        )
        if (prevIdx >= 0 && !prevStreamKey && streamKey) {
          const oldKey = `${assistantId}:tool:${prevIdx}`
          const newKey = `${assistantId}:tool:${streamKey}`
          const prevOpen = expandedCardKeysRef.current[oldKey]
          if (prevOpen !== undefined) {
            setCardExpanded(newKey, prevOpen)
          }
        }
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolArgsDelta: (toolCallId, delta, streamKey) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({ ...cur, args: (cur.args ?? '') + delta }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          deliveryState: promoteStreaming(m.deliveryState),
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolArgsSnapshot: (toolCallId, snapshot, streamKey) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({ ...cur, args: snapshot }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          deliveryState: promoteStreaming(m.deliveryState),
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolEnd: (toolCallId, streamKey) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({
            ...cur,
            status: cur.status === 'running' ? 'awaiting_result' : cur.status,
          }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolResultReady: ({ executionId, toolCallId, streamKey, isError }) => {
        const readyStatus = isError === true
          ? 'error'
          : isError === false
            ? 'completed'
            : 'result_ready'
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({
            ...cur,
            executionId,
            status: cur.status === 'error' ? 'error' : readyStatus,
          }),
          () => ({
            id: toolCallId,
            streamKey,
            executionId,
            name: 'tool',
            status: readyStatus,
          }),
        )
        const matchedIdx = findToolCallIndex(liveTools, { toolCallId, streamKey })
        const slotIdx = matchedIdx >= 0 ? matchedIdx : Math.max(0, liveTools.length - 1)
        const matchedBlock = liveTools[slotIdx]
        const cardKey = `${assistantId}:tool:${matchedBlock?.streamKey ?? slotIdx}`
        const explicitOpen = expandedCardKeysRef.current[cardKey]
        const isCardOpen = explicitOpen !== undefined
          ? explicitOpen
          : blockPrefsRef.current.tools === 'full'
        if (explicitOpen !== undefined) {
          setCardExpanded(cardKey, explicitOpen, executionId)
        }
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: snapshotTools,
        }), 'Streaming')
        if (
          canUseSingleUserTokenAdmin(authSession.peek())
          && blockPrefsRef.current.tools !== 'hidden'
          && isCardOpen
          && !matchedBlock?.result
        ) {
          void requestToolResult(executionId)
        }
      },
      onToolResult: (toolCallId, content, streamKey) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({ ...cur, result: content, status: cur.status === 'error' ? 'error' : 'completed' }),
          () => ({
            id: toolCallId || undefined,
            streamKey,
            name: 'tool',
            result: content,
            status: 'completed',
          }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onNativeToolProgress: ({ toolName, toolCallId, streamKey, progressLabel }) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({
            ...cur,
            name: toolName ?? cur.name,
            progressLabel,
          }),
          () => ({
            id: toolCallId,
            streamKey,
            name: toolName ?? 'native_tool',
            status: 'running',
            progressLabel,
          }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          deliveryState: promoteStreaming(m.deliveryState),
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onNativeToolEnd: ({ toolName, toolCallId, streamKey, status, summary }) => {
        liveTools = upsertStreamToolCall(
          liveTools,
          { toolCallId, streamKey },
          (cur) => ({
            ...cur,
            name: toolName ?? cur.name,
            status,
            progressLabel: summary ?? cur.progressLabel,
          }),
          () => ({
            id: toolCallId,
            streamKey,
            name: toolName ?? 'native_tool',
            status,
            progressLabel: summary,
          }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolApprovalRequested: ({ toolCallId, toolName, args, question, because }) => {
        const label = question ?? because ?? '운영자 승인 대기 중'
        const trimmedId = toolCallId.trim()
        const matchRef = trimmedId
          ? { toolCallId: trimmedId }
          : { streamKey: `approval:${randomUuid()}` }
        liveTools = upsertStreamToolCall(
          liveTools,
          matchRef,
          (cur) => ({
            ...cur,
            name: toolName || cur.name,
            args: args ?? cur.args,
            status: 'awaiting_approval',
            progressLabel: label,
          }),
          () => ({
            id: trimmedId || undefined,
            streamKey: matchRef.streamKey,
            name: toolName,
            args,
            status: 'awaiting_approval',
            progressLabel: label,
          }),
        )
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          deliveryState: promoteStreaming(m.deliveryState),
          toolCalls: snapshotTools,
        }), 'Streaming')
      },
      onToolApprovalSettled: ({ toolCallId, toolName, outcome: approvalOutcome }) => {
        const normalizedOutcome = approvalOutcome.trim().toLowerCase()
        const approved =
          normalizedOutcome === 'approve' || normalizedOutcome === 'remembered_approve'
        const trimmedId = toolCallId.trim()
        if (trimmedId) {
          liveTools = upsertStreamToolCall(
            liveTools,
            { toolCallId: trimmedId },
            (cur) => ({
              ...cur,
              status: approved ? 'running' : 'error',
              progressLabel: approvalOutcome,
            }),
          )
        } else {
          const list = [...liveTools]
          let targetIdx = -1
          for (let i = list.length - 1; i >= 0; i -= 1) {
            const cur = list[i]!
            if (cur.status !== 'awaiting_approval') continue
            if (!toolName || cur.name === toolName) {
              targetIdx = i
              break
            }
            if (targetIdx < 0) targetIdx = i
          }
          if (targetIdx >= 0) {
            list[targetIdx] = {
              ...list[targetIdx]!,
              status: approved ? 'running' : 'error',
              progressLabel: approvalOutcome,
            }
            liveTools = list
          }
        }
        const snapshotTools = liveTools
        updateAssistant((m) => ({
          ...m,
          toolCalls: snapshotTools.length > 0 ? snapshotTools : m.toolCalls,
        }), 'Streaming')
      },
      onReplyDetails: (reply, turnRef, turnOutcome) => {
        markUserDelivered()
        // Terminal_effect_settled (wire label "external_effect_completed") and
        // No_visible_reply ("no_visible_reply") never persist an assistant text
        // row; do not copy discarded diagnostic prose into the live bubble.
        const discardsProse =
          turnOutcome === 'external_effect_completed' || turnOutcome === 'no_visible_reply'
        updateAssistant((m) => ({
          ...m,
          content: discardsProse ? m.content : (reply || m.content),
          turnRef: turnRef ?? m.turnRef,
        }), 'Streaming')
      },
      onError: (msg) => {
        const settleOnError = (tc: ChatToolBlock): ChatToolBlock =>
          tc.status === 'running' || tc.status === 'awaiting_result' || tc.status === 'awaiting_approval'
            ? { ...tc, status: 'error' }
            : tc
        liveTools = liveTools.map(settleOnError)
        const snapshotTools = liveTools.length > 0 ? liveTools : undefined
        updateEntryById(userId, (m) => ({
          ...m,
          deliveryState: acceptedByServer ? 'Delivered' : 'Failed',
        }))
        updateAssistant((m) => ({
          ...m,
          deliveryState: 'Failed',
          errorDetail: msg,
          toolCalls: snapshotTools ?? m.toolCalls?.map(settleOnError),
        }), 'Failed')
      },
      onFinished: () => {
        markUserDelivered()
        const settleOnFinish = (tc: ChatToolBlock): ChatToolBlock =>
          tc.status === 'running' || tc.status === 'awaiting_result' || tc.status === 'awaiting_approval'
            ? { ...tc, status: tc.executionId || tc.result !== undefined ? 'completed' : 'interrupted' }
            : tc
        liveTools = liveTools.map(settleOnFinish)
        const snapshotTools = liveTools.length > 0 ? liveTools : undefined
        updateExistingAssistant((m) => ({
          ...m,
          deliveryState: m.deliveryState === 'Failed' ? 'Failed' : 'Delivered',
          toolCalls: snapshotTools ?? m.toolCalls?.map(settleOnFinish),
        }))
      },
    }
  }, [updateEntryById, setCardExpanded, requestToolResult])

  useEffect(() => {
    let stopped = false
    let drainScheduled = false
    let historyReadSeq = 0
    const pending = new Set<ChatRead>()
    const running = new Map<ChatRead, AbortController>()
    observerStreamsRef.current.clear()
    localOwnedOpIdsRef.current.clear()

    const abortReads = () => {
      for (const controller of running.values()) controller.abort()
      running.clear()
      pending.clear()
    }

    const refresh = (...reads: ChatRead[]) => {
      if (stopped) return
      for (const read of reads) pending.add(read)
      if (reads.includes('queue')) {
        const epoch = currentSessionEpoch()
        setQueueRead((previous) => {
          const sameScope = previous?.keeperName === keeper.name && previous.epoch === epoch
          if (sameScope && previous.kind === 'ready') {
            return { ...previous, refreshing: true }
          }
          return {
            keeperName: keeper.name,
            epoch,
            kind: 'loading',
            operations: sameScope ? previous.operations : [],
          }
        })
      }
      if (drainScheduled) return
      drainScheduled = true
      queueMicrotask(() => {
        drainScheduled = false
        if (stopped) return
        for (const read of pending) {
          if (running.has(read)) continue
          pending.delete(read)
          const controller = new AbortController()
          running.set(read, controller)
          const signal = controller.signal
          const epoch = currentSessionEpoch()
          const current = () => !signal.aborted
            && activeKeeperRef.current === keeper.name && isEpochCurrent(epoch)
          void readChat(read, signal, epoch, current).finally(() => {
            if (!current()) return
            running.delete(read)
            if (pending.has(read)) refresh()
          })
        }
      })
    }

    const readChat = async (read: ChatRead, signal: AbortSignal, epoch: number, current: () => boolean) => {
      switch (read) {
        case 'history': {
          const readStartedAtSeq = ++historyReadSeq
          const result = await fetchKeeperChatHistoryPageApi(keeper.name, undefined, 40, signal)
          if (!current()) return
          setLoadingHistory(false)
          setHistoryError(result.ok ? null : result.error.message)
          if (result.ok) {
            const authoritativeEmpty = result.value.messages.length === 0
            if (authoritativeEmpty) {
              invalidateEarlierReads()
              hasLoadedEarlierRef.current = false
            }
            const reconciledObserverOpIds = new Set<string>()
            for (const candidate of observerStreamsRef.current.values()) {
              if (
                candidate.terminal
                && candidate.completedAtHistorySeq !== null
                && readStartedAtSeq > candidate.completedAtHistorySeq
              ) {
                reconciledObserverOpIds.add(candidate.operationId)
              }
            }
            setMessagesState((previous) => ({
              keeperName: keeper.name,
              entries: mergeLatestHistoryPage(
                previous.keeperName === keeper.name ? previous.entries : [],
                result.value.messages,
                sendingOperationRef.current,
                reconciledObserverOpIds.size > 0 ? reconciledObserverOpIds : undefined,
              ),
            }))
            if (authoritativeEmpty || !hasLoadedEarlierRef.current) {
              setHasMore(authoritativeEmpty ? false : result.value.hasMore)
              setNextCursor(authoritativeEmpty ? null : result.value.nextCursor)
            }
          }
          return
        }
        case 'queue': {
          const result = await fetchQueuedChatOperations(keeper.name, signal)
          if (!current()) return
          const anotherReadPending = pending.has('queue')
          if (result.ok) {
            setQueueRead({
              keeperName: keeper.name,
              epoch,
              kind: 'ready',
              refreshing: anotherReadPending,
              operations: result.value,
            })
          } else {
            const { kind, message } = result.error
            const clear = kind === 'unauthorized' || kind === 'forbidden' || kind === 'epoch_stale'
            setQueueRead((previous) => {
              const sameScope = !clear && previous?.keeperName === keeper.name && previous.epoch === epoch
              const operations = sameScope ? previous.operations : []
              const scope = { keeperName: keeper.name, epoch, operations }
              if (anotherReadPending) {
                return sameScope && previous.kind === 'ready'
                  ? { ...scope, kind: 'ready', refreshing: true }
                  : { ...scope, kind: 'loading' }
              }
              return { ...scope, kind: 'error', message }
            })
          }
          return
        }
        case 'waiting': {
          const result = await fetchKeeperWaitingInventoryApi(keeper.name, signal)
          if (current() && result.ok) setWaitingInventory(result.value)
          return
        }
      }
    }

    const recover = () => {
      // The preceding connection's reads cannot settle this observation.
      abortReads()
      invalidateEarlierReads()
      invalidateTurn()
      refresh('history', 'queue', 'waiting')
    }

    refreshChatRef.current = refresh
    retryQueueRef.current = () => {
      running.get('queue')?.abort()
      running.delete('queue')
      refresh('queue')
    }
    const isOwnedLocally = (id: string): boolean => {
      if (localOwnedOpIdsRef.current.has(id)) return true
      const active = sendingOperationRef.current
      return sendingRef.current && active !== null
        && (active.operationId === id || active.executionId === id)
    }

    const hasOtherStreamForExecution = (executionId: string, exceptOpId: string): boolean => {
      for (const candidate of observerStreamsRef.current.values()) {
        if (candidate.operationId === exceptOpId || candidate.shadowed) continue
        if (candidate.operationId === executionId || candidate.executionId === executionId) {
          return true
        }
      }
      return false
    }

    const handleObserverOperationEvent = (
      event: Extract<KeeperObserverChatSignal, { readonly kind: 'chat_operation_event' }>,
    ) => {
      if (stopped || activeKeeperRef.current !== keeper.name) return
      const { operationId, seq, agUiEvent } = event
      if (isOwnedLocally(operationId)) return

      const streams = observerStreamsRef.current
      let stream = streams.get(operationId)
      if (stream) {
        if (stream.shadowed || stream.terminal) return
        if (seq !== null && !recordObserverSeq(stream, seq)) return
      } else {
        const currentEntries =
          messagesStateRef.current.keeperName === keeper.name
            ? messagesStateRef.current.entries
            : []
        if (isOperationSettledInEntries(currentEntries, operationId)) return

        const agType = nonBlankStr(agUiEvent.type)
        const agCustomName = agType === 'CUSTOM' ? nonBlankStr(agUiEvent.name) : null
        const agCustomVal = agType === 'CUSTOM' && isRecordLike(agUiEvent.value) ? agUiEvent.value : null
        const isLoneTerminalFinish =
          agType === 'RUN_FINISHED'
          || (agCustomName === 'KEEPER_CHAT_OPERATION_ACCEPTED'
            && agCustomVal !== null
            && (agCustomVal.state === 'Succeeded'
              || agCustomVal.state === 'Failed'
              || agCustomVal.state === 'Cancelled'))

        if (isLoneTerminalFinish) {
          const settledMarker: ObserverOperationStream = {
            operationId,
            executionId: operationId,
            assistantId: `obs-asst-${operationId}`,
            dispatcher: null,
            seenSeqs: new Set<number>(),
            evictedSeqWatermark: -1,
            entryCreated: false,
            terminal: true,
            completedAtHistorySeq: historyReadSeq,
            shadowed: false,
          }
          if (seq !== null) recordObserverSeq(settledMarker, seq)
          setBoundedObserverStream(streams, operationId, settledMarker)
          refresh('history', 'queue', 'waiting')
          return
        }

        if (agCustomName === 'KEEPER_CHAT_BATCH_BOUND' && agCustomVal) {
          const boundExecId = nonBlankStr(agCustomVal.execution_id)
          if (
            boundExecId
            && (isOwnedLocally(boundExecId)
              || hasOtherStreamForExecution(boundExecId, operationId)
              || isOperationSettledInEntries(currentEntries, boundExecId))
          ) {
            const shadowedMarker: ObserverOperationStream = {
              operationId,
              executionId: boundExecId,
              assistantId: `obs-asst-${operationId}`,
              dispatcher: null,
              seenSeqs: new Set<number>(),
              evictedSeqWatermark: -1,
              entryCreated: false,
              terminal: true,
              completedAtHistorySeq: historyReadSeq,
              shadowed: true,
            }
            if (seq !== null) recordObserverSeq(shadowedMarker, seq)
            setBoundedObserverStream(streams, operationId, shadowedMarker)
            return
          }
        }

        const targetKeeper = keeper.name
        const streamEpoch = currentSessionEpoch()
        const assistantId = `obs-asst-${operationId}`
        const userId = `user-${operationId}`

        const nextStream: ObserverOperationStream = {
          operationId,
          executionId: operationId,
          assistantId,
          dispatcher: null,
          seenSeqs: new Set<number>(),
          evictedSeqWatermark: -1,
          entryCreated: false,
          terminal: false,
          completedAtHistorySeq: null,
          shadowed: false,
        }

        const updateObserverAssistant = (
          updater: (cur: ChatTranscriptEntry) => ChatTranscriptEntry,
          initialDelivery: ChatDeliveryState = 'Streaming',
        ) => {
          if (stopped || nextStream.shadowed || !isEpochCurrent(streamEpoch)) return
          setMessagesState((prev) => {
            if (prev.keeperName !== targetKeeper) return prev
            const exists = prev.entries.some((m) => m.id === assistantId)
            if (exists) {
              return {
                keeperName: prev.keeperName,
                entries: prev.entries.map((m) => (m.id === assistantId ? updater(m) : m)),
              }
            }
            if (nextStream.entryCreated) return prev
            if (
              isOperationSettledInEntries(prev.entries, operationId)
              || (nextStream.executionId !== operationId
                && isOperationSettledInEntries(prev.entries, nextStream.executionId))
            ) {
              nextStream.terminal = true
              return prev
            }
            nextStream.entryCreated = true
            const baseEntry: ChatTranscriptEntry = {
              id: assistantId,
              role: 'assistant',
              content: '',
              ts: Date.now() / 1000,
              operationId,
              replyOperationId:
                nextStream.executionId !== operationId ? nextStream.executionId : undefined,
              deliveryState: initialDelivery,
            }
            return {
              keeperName: prev.keeperName,
              entries: [...prev.entries, updater(baseEntry)],
            }
          })
        }

        const updateExistingObserverAssistant = (
          updater: (cur: ChatTranscriptEntry) => ChatTranscriptEntry,
        ) => {
          if (stopped || nextStream.shadowed || !isEpochCurrent(streamEpoch)) return
          updateEntryById(assistantId, updater)
        }

        const dispatcher = createChatStreamFrameDispatcher({
          operationId,
          startEpoch: streamEpoch,
          callbacks: createAssistantStreamCallbacks({
            assistantId,
            userId,
            initialAcceptedByServer: true,
            updateAssistant: updateObserverAssistant,
            updateExistingAssistant: updateExistingObserverAssistant,
            onBatchBound: (memberId, executionId) => {
              if (memberId !== operationId || nextStream.shadowed) return
              if (
                isOwnedLocally(executionId)
                || hasOtherStreamForExecution(executionId, operationId)
                || isOperationSettledInEntries(
                  messagesStateRef.current.keeperName === targetKeeper
                    ? messagesStateRef.current.entries
                    : [],
                  executionId,
                )
              ) {
                nextStream.shadowed = true
                nextStream.terminal = true
                if (nextStream.entryCreated) {
                  setMessagesState((prev) => {
                    if (prev.keeperName !== targetKeeper) return prev
                    if (!prev.entries.some((m) => m.id === assistantId)) return prev
                    return {
                      keeperName: prev.keeperName,
                      entries: prev.entries.filter((m) => m.id !== assistantId),
                    }
                  })
                }
                return
              }
              nextStream.executionId = executionId
              if (nextStream.entryCreated) {
                updateEntryById(assistantId, (entry) => ({
                  ...entry,
                  replyOperationId: executionId,
                }))
              }
            },
          }),
        })

        nextStream.dispatcher = dispatcher
        stream = nextStream
        if (seq !== null) recordObserverSeq(stream, seq)
        setBoundedObserverStream(streams, operationId, stream)
      }

      if (!stream.dispatcher || stream.shadowed || stream.terminal) return
      const outcome = stream.dispatcher.dispatch(agUiEvent)
      if (outcome.terminal && !stream.shadowed) {
        stream.terminal = true
        stream.completedAtHistorySeq = historyReadSeq
        refresh('history', 'queue', 'waiting')
      }
    }

    const unsubscribeFrames = subscribeObserverFrames((frame) => {
      const event = parseKeeperLiveObserverEvent(frame.event, frame.data, keeper.name)
      switch (event?.kind) {
        case 'turn_preview': {
          if (!event.ownerKey) break
          const sample = { ownerKey: event.ownerKey, preview: event.preview, receivedAt: Date.now(), live: true }
          const owner = turnOwnerRef.current
          const snapshot = lastTurn.current
          const retiredOwners = snapshot?.keeper === keeper.name && isEpochCurrent(snapshot.epoch)
            ? snapshot.retiredOwners : undefined
          setTurnPreviews((previous) => retainTurnPreview(previous, owner, sample, retiredOwners))
          break
        }
        case 'turn_changed':
          invalidateTurn()
          break
        case 'turn_succeeded':
          setLastWorked((previous) => previous && previous.atUnix >= event.atUnix ? previous : event)
          break
        case 'chat_appended':
          refresh('history')
          break
        case 'waiting_changed':
          refresh('waiting')
          if (event.queueChanged) refresh('queue')
          break
        case 'chat_operation_event':
          handleObserverOperationEvent(event)
          break
        case undefined:
          break
      }
    })
    const unsubscribeResync = subscribeObserverResync(recover)
    let wasConnected = observerConnected.peek()
    const unsubscribeConnection = observerConnected.subscribe((connected) => {
      if (connected && !wasConnected) recover()
      wasConnected = connected
    })
    let epoch = currentSessionEpoch()
    const unsubscribeEpoch = sessionEpoch.subscribe((nextEpoch) => {
      if (nextEpoch === epoch) return
      epoch = nextEpoch
      observerStreamsRef.current.clear()
      localOwnedOpIdsRef.current.clear()
      setMessagesState({ keeperName: keeper.name, entries: [] })
      setQueueRead(null)
      setHasMore(false)
      setNextCursor(null)
      setWaitingInventory(null)
      setLastWorked(null)
      setTurnPreviews([])
      setHistoryError(null)
      setLoadingHistory(true)
      btwAbortRef.current?.abort()
      setBtwOpen(false)
      setBtw({ status: 'idle', prompt: '', reply: '', error: null })
      recover()
    })
    setLoadingHistory(true)
    setHistoryError(null)
    refresh('history', 'queue', 'waiting')
    return () => {
      stopped = true
      abortReads()
      invalidateEarlierReads()
      unsubscribeFrames()
      unsubscribeResync()
      unsubscribeConnection()
      unsubscribeEpoch()
      observerStreamsRef.current.clear()
      localOwnedOpIdsRef.current.clear()
      refreshChatRef.current = () => {}
      retryQueueRef.current = () => {}
      streamRunIdRef.current += 1
      sendingRef.current = false
      sendingOperationRef.current = null
      followUpSubmittingRef.current = false
      streamAbortRef.current?.abort()
      btwAbortRef.current?.abort()
    }
  }, [keeper.name, invalidateEarlierReads, invalidateTurn, updateEntryById, createAssistantStreamCallbacks])

  const updateQueueOperation = async (
    operationId: string,
    action: typeof moveQueuedChatOperationToEndApi,
  ) => {
    if (queue?.kind !== 'ready' || queue.refreshing === true || !isEpochCurrent(queue.epoch) || activeKeeperRef.current !== keeper.name) return
    const targetKeeper = keeper.name
    const startEpoch = queue.epoch
    const res = await action(targetKeeper, operationId)
    if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch)) return
    if (!res.ok) {
      setHistoryError(`대기열 작업 실패: ${res.error.message}`)
      return
    }
    refreshChatRef.current('queue', 'waiting')
  }

  // Global shortcuts: ⌘. / Ctrl+. (Debug Companion) and Alt+T (Thinking block visibility)
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.defaultPrevented || e.isComposing || e.keyCode === 229) return
      if (typeof document !== 'undefined' && document.querySelector('[role="dialog"][aria-modal="true"]')) return
      if ((e.metaKey || e.ctrlKey) && !e.altKey && e.key === '.') {
        e.preventDefault()
        setCompanionOpen((prev) => !prev)
        return
      }
      if (e.altKey && !e.metaKey && !e.ctrlKey && !e.shiftKey && (e.code === 'KeyT' || e.key.toLowerCase() === 't')) {
        e.preventDefault()
        updateBlockPrefs((cur) => ({ ...cur, thinking: nextThinkingMode(cur.thinking) }))
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [updateBlockPrefs])

  const handleLoadEarlier = async () => {
    if (!nextCursor || loadingHistory) return
    const targetKeeper = keeper.name
    const startEpoch = currentSessionEpoch()
    earlierAbortRef.current?.abort()
    const ctrl = new AbortController()
    earlierAbortRef.current = ctrl
    const reqGen = ++earlierGenRef.current
    setLoadingHistory(true)
    const res = await fetchKeeperChatHistoryPageApi(targetKeeper, nextCursor, 40, ctrl.signal)
    if (
      !mountedRef.current
      || activeKeeperRef.current !== targetKeeper
      || !isEpochCurrent(startEpoch)
      || ctrl.signal.aborted
      || reqGen !== earlierGenRef.current
    ) {
      return
    }
    if (earlierAbortRef.current === ctrl) {
      earlierAbortRef.current = null
    }
    setLoadingHistory(false)
    if (!res.ok) {
      if (res.error.kind !== 'epoch_stale' && res.error.kind !== 'aborted') {
        setHistoryError(res.error.message)
      }
      return
    }
    const el = chatListRef.current
    if (el) {
      pendingPrependAnchorRef.current = {
        prevScrollHeight: el.scrollHeight,
        prevScrollTop: el.scrollTop,
      }
    }
    setRenderWindow((cur) => Math.min(MAX_RENDER_WINDOW, cur + res.value.messages.length))
    hasLoadedEarlierRef.current = true
    setMessagesState((prev) => {
      const baseEntries = prev.keeperName === targetKeeper ? prev.entries : []
      const existingIds = new Set(baseEntries.map((m) => m.id))
      const fresh = res.value.messages.filter((m) => !existingIds.has(m.id))
      return {
        keeperName: targetKeeper,
        entries: [...dedupeHistoryToolRows([...fresh, ...baseEntries])],
      }
    })
    setHasMore(res.value.hasMore)
    setNextCursor(res.value.nextCursor)
  }

  const handleRecoverCut = async (
    assistantId: string,
    operationId: string,
    opts?: {
      readonly userId?: string
      readonly unconfirmedAcceptance?: boolean
      readonly streamError?: string | null
    },
  ) => {
    if (!opts?.unconfirmedAcceptance && !canUseSingleUserTokenAdmin(authSession.peek())) {
      updateAssistantEntry(assistantId, (m) => ({
        ...m,
        cutStream: false,
        deliveryState: m.content ? 'Delivered' : 'Failed',
        errorDetail: m.content ? undefined : '스트림이 중단되었습니다. 대화 이력을 새로고침했습니다.',
      }))
      refreshChatRef.current('history', 'queue', 'waiting')
      return
    }
    const targetKeeper = keeper.name
    const startEpoch = currentSessionEpoch()
    const stillActive = () =>
      mountedRef.current && activeKeeperRef.current === targetKeeper && isEpochCurrent(startEpoch)
    if (opts?.unconfirmedAcceptance && opts.userId) {
      updateEntryById(opts.userId, (m) => ({
        ...m,
        deliveryState: 'Confirming_delivery',
      }))
    }
    updateAssistantEntry(assistantId, (m) => ({
      ...m,
      deliveryState: 'Confirming_delivery',
    }))
    const recovered = await recoverCutReplyFromJournal(targetKeeper, operationId)
    if (!stillActive()) return
    if (opts?.unconfirmedAcceptance) {
      if (recovered.ok && recovered.value.eventCount > 0) {
        if (opts.userId) {
          updateEntryById(opts.userId, (m) => ({
            ...m,
            deliveryState: 'Delivered',
            errorDetail: undefined,
          }))
        }
        updateAssistantEntry(assistantId, (m) => ({
          ...m,
          content: recovered.value.text || m.content,
          replyOperationId: recovered.value.executionId ?? m.replyOperationId,
          deliveryState: recovered.value.error ? 'Failed' : 'Cut_recovered',
          cutStream: false,
          errorDetail: recovered.value.error ?? undefined,
        }))
        refreshChatRef.current('history')
        return
      }
      if (!recovered.ok && (recovered.error.kind === 'epoch_stale' || recovered.error.kind === 'aborted')) {
        return
      }
      const queueRes = await fetchQueuedChatOperations(targetKeeper)
      if (!stillActive()) return
      if (queueRes.ok) {
        const queuedOp = queueRes.value.find((op) => op.operationId === operationId)
        if (queuedOp) {
          const accepted = acceptedReplyState(queuedOp.state)
          if (opts.userId) {
            updateEntryById(opts.userId, (m) => ({
              ...m,
              deliveryState: queuedOp.state === 'Queued' ? 'Queued' : 'Delivered',
              errorDetail: undefined,
            }))
          }
          updateAssistantEntry(assistantId, (m) => ({
            ...m,
            deliveryState: accepted.delivery,
            cutStream: false,
            errorDetail: accepted.detail ?? m.errorDetail,
          }))
          refreshChatRef.current('queue', 'waiting')
          return
        }
        if (recovered.ok) {
          const errText = opts.streamError ?? '전송 실패'
          if (opts.userId) {
            updateEntryById(opts.userId, (m) => ({
              ...m,
              deliveryState: 'Failed',
              errorDetail: errText,
            }))
          }
          updateAssistantEntry(assistantId, (m) => ({
            ...m,
            deliveryState: 'Failed',
            cutStream: false,
            errorDetail: errText,
          }))
          return
        }
      } else if (queueRes.error.kind === 'epoch_stale' || queueRes.error.kind === 'aborted') {
        return
      }
      const uncertainDetail = '수락 여부 확인 실패 — 중복 전송 방지를 위해 새로고침 후 확인하세요'
      if (opts.userId) {
        updateEntryById(opts.userId, (m) => ({
          ...m,
          deliveryState: 'Confirming_delivery',
          errorDetail: uncertainDetail,
        }))
      }
      updateAssistantEntry(assistantId, (m) => ({
        ...m,
        deliveryState: 'Confirming_delivery',
        errorDetail: uncertainDetail,
      }))
      return
    }
    if (!recovered.ok) {
      if (recovered.error.kind === 'epoch_stale' || recovered.error.kind === 'aborted') return
      updateAssistantEntry(assistantId, (m) => ({
        ...m,
        deliveryState: 'Failed',
        errorDetail: `저널 복구 실패: ${recovered.error.message}`,
      }))
      return
    }
    updateAssistantEntry(assistantId, (m) => ({
      ...m,
      content: recovered.value.text || m.content,
      replyOperationId: recovered.value.executionId ?? m.replyOperationId,
      deliveryState: recovered.value.error ? 'Failed' : 'Cut_recovered',
      cutStream: false,
      errorDetail: recovered.value.error ?? undefined,
    }))
    refreshChatRef.current('history')
  }

  const runBtwQuery = async (promptText: string) => {
    const trimmed = promptText.trim()
    if (!trimmed) return
    const targetKeeper = keeper.name
    const startEpoch = currentSessionEpoch()
    btwAbortRef.current?.abort()
    const btwController = new AbortController()
    btwAbortRef.current = btwController
    const isStillActive = () =>
      mountedRef.current
      && activeKeeperRef.current === targetKeeper
      && isEpochCurrent(startEpoch)
      && !btwController.signal.aborted
    setBtwOpen(true)
    setBtw({ status: 'streaming', prompt: trimmed, reply: '', error: null })
    const operationId = `btw-${randomUuid()}`
    recordLocalOwnedOp(operationId)
    const outcome = await streamKeeperChat({
      keeper: targetKeeper,
      message: trimmed,
      operationId,
      mode: { kind: 'btw' },
      signal: btwController.signal,
      callbacks: {
        onTextDelta: (delta) => {
          if (!isStillActive()) return
          setBtw((cur) => ({ ...cur, reply: cur.reply + delta }))
        },
        onReplyDetails: (reply) => {
          if (!isStillActive()) return
          setBtw((cur) => ({ ...cur, reply: reply || cur.reply }))
        },
        onError: (msg) => {
          if (!isStillActive()) return
          setBtw((cur) => ({ ...cur, status: 'error', error: msg }))
        },
        onFinished: () => {
          if (!isStillActive()) return
          setBtw((cur) => ({ ...cur, status: cur.status === 'error' ? 'error' : 'done' }))
        },
      },
    })
    if (!outcome.terminal && isStillActive()) {
      if (outcome.error) {
        if (outcome.error !== 'aborted' && outcome.error !== 'session_epoch_changed') {
          setBtw((cur) => (cur.status === 'error' ? cur : { ...cur, status: 'error', error: outcome.error }))
        }
      } else if (!canUseSingleUserTokenAdmin(authSession.peek())) {
        setBtw((cur) => ({
          ...cur,
          status: cur.reply ? 'done' : 'error',
          error: cur.reply ? null : '스트림이 중단되었습니다. 다시 시도하세요.',
        }))
      } else {
        const rec = await recoverCutReplyFromJournal(targetKeeper, operationId)
        if (!isStillActive()) return
        if (rec.ok) {
          setBtw((cur) => ({
            ...cur,
            status: rec.value.error ? 'error' : 'done',
            reply: rec.value.text || cur.reply,
            error: rec.value.error,
          }))
        } else if (rec.error.kind !== 'aborted' && rec.error.kind !== 'epoch_stale') {
          setBtw((cur) => ({
            ...cur,
            status: 'error',
            error: rec.error.message,
          }))
        }
      }
    }
  }

  const submitMessage = async (intent: 'queue' | 'steer') => {
    if (followUpSubmittingRef.current) return
    if (hasUploadingAttachments(composerAttachmentsRef.current)) {
      setHistoryError('첨부 파일 업로드가 완료된 뒤 전송하세요.')
      return
    }
    if (hasFailedAttachments(composerAttachmentsRef.current)) {
      setHistoryError('업로드에 실패한 첨부 파일을 재시도하거나 제거한 뒤 전송하세요.')
      return
    }
    const trimmed = draftRef.current.trim()
    const readyAttachments = readyAttachmentsOf(composerAttachmentsRef.current)
    if (!trimmed && readyAttachments.length === 0) return

    // `/btw <question>` shortcut inside main composer (bare `/btw` opens the side-query box)
    if (/^\/btw(?:\s|$)/.test(trimmed)) {
      const sidePrompt = trimmed.slice(4).trim()
      draftRef.current = ''
      setDraft('')
      if (!sidePrompt) {
        setBtwOpen(true)
        return
      }
      await runBtwQuery(sidePrompt)
      return
    }

    const targetKeeper = keeper.name
    const startEpoch = currentSessionEpoch()
    const operationId = `op-${randomUuid()}`
    const nowSec = Date.now() / 1000
    const userId = `user-${operationId}`
    const userEntry: ChatTranscriptEntry = {
      id: userId,
      role: 'user',
      speakerLabel: 'Operator',
      content: trimmed,
      attachments: readyAttachments.length > 0 ? readyAttachments : undefined,
      ts: nowSec,
      operationId,
      deliveryState: 'Sending',
    }
    const currentAttachments = [...readyAttachments]

    // While a turn is already streaming on the Layer 3 view-stream slot:
    // - Queue submits via a short-lived acceptance request so the active stream is NOT aborted.
    // - Steer preempts the active stream cleanly (after fetching controlToken) and hands off
    //   the live slot to the steering turn.
    if (sendingRef.current && intent === 'queue') {
      followUpSubmittingRef.current = true
      setFollowUpSubmitting(true)
      forceScrollBottomRef.current = true
      setMessagesState((prev) => ({
        keeperName: targetKeeper,
        entries: prev.keeperName === targetKeeper ? [...prev.entries, userEntry] : [userEntry],
      }))
      draftRef.current = ''
      setDraft('')
      clearComposerAttachments()
      queueMicrotask(() => composerRef.current?.focus())
      try {
        const res = await enqueueKeeperChat({
          keeper: targetKeeper,
          message: trimmed,
          operationId,
          mode: { kind: 'queue' },
          attachments: currentAttachments,
        })
        if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch)) {
          return
        }
        if (res.controlToken) setControlToken(res.controlToken)
        if (!res.accepted) {
          if (res.error === 'session_epoch_changed' || res.error === 'aborted') {
            return
          }
          if (res.rejected) {
            updateEntryById(userId, (m) => ({
              ...m,
              deliveryState: 'Failed',
              errorDetail: res.error ?? '대기열 등록 실패',
            }))
            return
          }
          // Unconfirmed transport drop / EOF without ACCEPTED: reconcile by
          // operationId against queue and journal before marking Failed so
          // retrying does not duplicate an already-persisted follow-up.
          updateEntryById(userId, (m) => ({
            ...m,
            deliveryState: 'Confirming_delivery',
            errorDetail: undefined,
          }))
          const queueRes = await fetchQueuedChatOperations(targetKeeper)
          if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch)) {
            return
          }
          const queuedOp = queueRes.ok
            ? queueRes.value.find((op) => op.operationId === operationId)
            : undefined
          if (queuedOp) {
            const accepted = acceptedReplyState(queuedOp.state)
            updateEntryById(userId, (m) => ({
              ...m,
              deliveryState: queuedOp.state === 'Queued' ? 'Queued' : accepted.delivery,
              errorDetail: accepted.detail ?? undefined,
            }))
          } else {
            const journalRes = await recoverCutReplyFromJournal(targetKeeper, operationId)
            if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch)) {
              return
            }
            if (journalRes.ok && journalRes.value.eventCount > 0) {
              updateEntryById(userId, (m) => ({
                ...m,
                deliveryState: journalRes.value.error ? 'Failed' : 'Delivered',
                errorDetail: journalRes.value.error ?? undefined,
              }))
            } else if (queueRes.ok && journalRes.ok) {
              updateEntryById(userId, (m) => ({
                ...m,
                deliveryState: 'Failed',
                errorDetail: res.error ?? '대기열 등록 실패',
              }))
            } else {
              updateEntryById(userId, (m) => ({
                ...m,
                deliveryState: 'Confirming_delivery',
                errorDetail: '수락 여부 확인 실패 — 중복 전송 방지를 위해 새로고침 후 확인하세요',
              }))
            }
          }
          refreshChatRef.current('queue', 'waiting')
          props.onMutated()
          return
        }
        const accepted = acceptedReplyState(res.state ?? '')
        updateEntryById(userId, (m) => ({
          ...m,
          deliveryState: accepted.delivery,
          errorDetail: accepted.detail ?? m.errorDetail,
        }))
        refreshChatRef.current('queue', 'waiting')
        props.onMutated()
      } finally {
        followUpSubmittingRef.current = false
        if (mountedRef.current) setFollowUpSubmitting(false)
      }
      return
    }

    const runId = ++streamRunIdRef.current
    const assistantId = `asst-${operationId}`
    const assistantEntry: ChatTranscriptEntry = {
      id: assistantId,
      role: 'assistant',
      content: '',
      ts: nowSec,
      operationId,
      deliveryState: 'Sending',
    }

    sendingRef.current = true
    sendingOperationRef.current = { operationId, executionId: operationId }
    recordLocalOwnedOp(operationId)
    shadowObserverStreamsForExecution(operationId)
    forceScrollBottomRef.current = true
    setMessagesState((prev) => ({
      keeperName: targetKeeper,
      entries: prev.keeperName === targetKeeper
        ? [...prev.entries, userEntry, assistantEntry]
        : [userEntry, assistantEntry],
    }))
    draftRef.current = ''
    setDraft('')
    clearComposerAttachments()
    setSending(true)
    queueMicrotask(() => composerRef.current?.focus())

    let abortController: AbortController | null = null
    let acceptedByServer = false
    let outcome: { readonly terminal: boolean; readonly error: string | null } = {
      terminal: false,
      error: null,
    }
    try {
      let submitMode: { readonly kind: 'queue' } | { readonly kind: 'steer'; readonly controlToken: string } = {
        kind: 'queue',
      }
      if (intent === 'steer') {
        const token = controlToken ?? (await fetchKeeperControlToken(targetKeeper))
        if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch) || streamRunIdRef.current !== runId) {
          return
        }
        if (token) {
          setControlToken(token)
          submitMode = { kind: 'steer', controlToken: token }
        }
      }

      if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch) || streamRunIdRef.current !== runId) {
        return
      }

      streamAbortRef.current?.abort('steered')
      abortController = new AbortController()
      streamAbortRef.current = abortController

      outcome = await streamKeeperChat({
        keeper: targetKeeper,
        message: trimmed,
        operationId,
        mode: submitMode,
        attachments: currentAttachments,
        signal: abortController.signal,
        callbacks: createAssistantStreamCallbacks({
          assistantId,
          userId,
          initialAcceptedByServer: false,
          onServerAccepted: () => { acceptedByServer = true },
          updateAssistant: (updater) => updateAssistantEntry(assistantId, updater),
          updateExistingAssistant: (updater) => updateAssistantEntry(assistantId, updater),
          onBatchBound: (memberId, executionId) => {
            if (memberId !== operationId) return
            sendingOperationRef.current = { operationId, executionId }
            recordLocalOwnedOp(executionId)
            shadowObserverStreamsForExecution(executionId)
            updateAssistantEntry(assistantId, (entry) => ({ ...entry, replyOperationId: executionId }))
          },
        }),
      })
    } finally {
      if (streamRunIdRef.current === runId) {
        sendingRef.current = false
        sendingOperationRef.current = null
        if (mountedRef.current) {
          setSending(false)
        }
      }
    }

    if (
      !mountedRef.current
      || activeKeeperRef.current !== targetKeeper
      || !isEpochCurrent(startEpoch)
      || streamRunIdRef.current !== runId
      || outcome.error === 'session_epoch_changed'
      || outcome.error === 'aborted'
    ) {
      return
    }

    // Mid-stream cut without RUN_FINISHED -> explicit HTTP rejection already
    // returned terminal=true via onError. Any non-terminal cut here either had
    // acceptance confirmed or dropped mid-transport with uncertain server receipt;
    // reconcile against journal + queue by operationId before concluding Failed.
    if (!outcome.terminal && !abortController?.signal.aborted) {
      if (acceptedByServer) {
        updateEntryById(userId, (m) => (m.deliveryState === 'Sending' ? { ...m, deliveryState: 'Delivered' } : m))
        updateAssistantEntry(assistantId, (m) => ({
          ...m,
          cutStream: true,
          deliveryState: 'Confirming_delivery',
        }))
        await handleRecoverCut(assistantId, operationId)
      } else {
        updateEntryById(userId, (m) => ({ ...m, deliveryState: 'Confirming_delivery' }))
        updateAssistantEntry(assistantId, (m) => ({
          ...m,
          cutStream: true,
          deliveryState: 'Confirming_delivery',
        }))
        await handleRecoverCut(assistantId, operationId, {
          userId,
          unconfirmedAcceptance: true,
          streamError: outcome.error,
        })
      }
    }

    if (!mountedRef.current || activeKeeperRef.current !== targetKeeper || !isEpochCurrent(startEpoch)) {
      return
    }

    refreshChatRef.current('history', 'queue', 'waiting')
    props.onMutated()
  }

  const handleComposerKeyDown = (e: KeyboardEvent) => {
    // Guard Korean/CJK IME composition & brief follow-up enqueue handshake
    if (e.isComposing || e.keyCode === 229) return
    if (e.key !== 'Enter') return
    if (e.shiftKey) return
    e.preventDefault()
    if (followUpSubmittingRef.current) return
    if (e.metaKey || e.ctrlKey) {
      void submitMessage('steer')
    } else {
      void submitMessage('queue')
    }
  }

  const handleVoiceFile = async (e: Event) => {
    const input = e.currentTarget as HTMLInputElement
    if (!canUseSingleUserTokenAdmin(authSession.peek())) {
      input.value = ''
      return
    }
    const file = input.files?.[0]
    if (!file) return
    setVoiceBusy(true)
    try {
      const buf = await file.arrayBuffer()
      const res = await transcribeVoiceAudio(buf, file.type || 'audio/webm')
      if (res.ok && res.value.trim()) {
        setDraft((cur) => (cur.trim() ? `${cur.trim()} ${res.value.trim()}` : res.value.trim()))
      }
    } finally {
      setVoiceBusy(false)
      input.value = ''
    }
  }

  const ctxObs = observeRosterContextPct(keeper)
  const ctxPct = ctxObs.kind === 'value' ? ctxObs.data : null
  const ringOffset = ctxPct !== null
    ? RING_CIRCUMFERENCE * (1 - ctxPct / 100)
    : RING_CIRCUMFERENCE
  const ringTone = contextSeverityTone(ctxPct)

  const parsedEntries = useMemo(
    () => scopedMessages.slice(-renderWindow).map((msg) => ({ msg, blocks: parseChatMessageBlocks(msg) })),
    [scopedMessages, renderWindow],
  )
  const { hiddenInternalCount, visibleEntries, displayItems } = useMemo(() => {
    let hidden = 0
    const visible = []
    for (let i = 0; i < parsedEntries.length; i++) {
      const entry = parsedEntries[i]!
      if (entry.blocks.isInternalOnly && blockPrefs.internal === 'hidden') {
        hidden += 1
      }
      if (shouldRenderChatEntry(entry.msg, entry.blocks, blockPrefs)) {
        visible.push(entry)
      }
    }
    return {
      hiddenInternalCount: hidden,
      visibleEntries: visible,
      displayItems: groupTranscriptEntries(visible),
    }
  }, [parsedEntries, blockPrefs])

  // Bounded auto-hydration for `Tools: full` (latest 8 visible cards) plus
  // immediate hydration for explicitly user-opened cards once `executionId` attaches.
  const explicitExpandedExecIds: string[] = []
  const fullModeVisibleExecIds: string[] = []
  if (blockPrefs.tools !== 'hidden') {
    const collectHydrationTarget = (
      tb: ChatToolBlock,
      idx: number,
      keyPrefix: string,
      parentOpen: boolean,
    ) => {
      const eid = tb.executionId?.trim()
      if (!eid || tb.result) return
      const cardKey = `${keyPrefix}:tool:${tb.streamKey ?? idx}`
      const explicit = expandedCardKeys[cardKey] ?? expandedCardKeys[`exec:${eid}`]
      if (explicit === true) {
        explicitExpandedExecIds.push(eid)
      } else if (blockPrefs.tools === 'full' && explicit !== false && parentOpen) {
        fullModeVisibleExecIds.push(eid)
      }
    }

    for (const item of displayItems) {
      if (item.kind === 'tool_group') {
        if (item.toolBlocks.length === 1) {
          const singleEntry = item.entries[0]!
          collectHydrationTarget(singleEntry.blocks.toolBlocks[0]!, 0, singleEntry.msg.id, true)
        } else {
          const groupOpen = expandedCardKeys[item.id] ?? (blockPrefs.tools === 'full')
          for (const entry of item.entries) {
            entry.blocks.toolBlocks.forEach((tb, tbIdx) => {
              collectHydrationTarget(tb, tbIdx, entry.msg.id, groupOpen)
            })
          }
        }
      } else {
        const { msg, blocks } = item.entry
        if (blocks.toolBlocks.length === 1) {
          collectHydrationTarget(blocks.toolBlocks[0]!, 0, msg.id, true)
        } else if (blocks.toolBlocks.length > 1) {
          const turnGroupKey = `turn-tools:${msg.id}`
          const hasInFlight = blocks.toolBlocks.some(
            (tb) => tb.status === 'running' || tb.status === 'awaiting_result' || tb.status === 'awaiting_approval',
          )
          if (hasInFlight) autoOpenedGroupsRef.current.add(turnGroupKey)
          const groupOpen =
            expandedCardKeys[turnGroupKey]
            ?? (blockPrefs.tools === 'full' || autoOpenedGroupsRef.current.has(turnGroupKey))
          blocks.toolBlocks.forEach((tb, tbIdx) => {
            collectHydrationTarget(tb, tbIdx, msg.id, groupOpen)
          })
        }
      }
    }
  }
  const boundedFullExecIds = fullModeVisibleExecIds.slice(-MAX_AUTO_HYDRATE_TOOL_RESULTS)
  const autoHydrateTargets = Array.from(new Set([...explicitExpandedExecIds, ...boundedFullExecIds]))
  const autoHydrateKey = autoHydrateTargets.join('\0')

  useEffect(() => {
    if (!canAdminLocalChat || !autoHydrateKey) return
    const targets = autoHydrateKey.split('\0').filter(Boolean)
    for (const eid of targets) {
      if (!toolResultCacheRef.current[eid] && !requestedExecIdsRef.current.has(eid)) {
        void requestToolResult(eid)
      }
    }
  }, [canAdminLocalChat, autoHydrateKey, keeper.name, blockPrefs.tools, requestToolResult])

  const matchedPreview = previewForObservedTurn(turnPreviews, activeTurn, snapshot?.updatedAt, snapshot?.retiredOwners)
  const effectivePreview = matchedPreview?.preview ?? activeTurn?.preview ?? null
  const openWork = effectivePreview?.open_activities ?? null
  const hasTurnObservation = activeTurn !== null || effectivePreview !== null
  const browserRequestQueued = sending && scopedMessages.some((entry) => entry.role === 'assistant'
    && entry.operationId === sendingOperationRef.current?.operationId && entry.deliveryState === 'Queued')
  const hasActiveObserverStream = scopedMessages.some((entry) => entry.role === 'assistant'
    && entry.id.startsWith('obs-asst-') && entry.deliveryState === 'Streaming')
  const showLiveTurnCard = (!sending || browserRequestQueued) && !hasActiveObserverStream && hasTurnObservation
  const liveTurnActivity = formatTurnActivityLabel(effectivePreview?.activity)
  const turnWorkContext = effectivePreview?.work_context ?? null
  // The one line the open-work rows expand: a preparation step, the open work, or the activity's word.
  const liveTurnDoing = effectivePreview ? turnDoing(effectivePreview) : null
  const liveTurnTone = liveTurnDoing?.tone ?? liveTurnActivity.tone
  const liveTurnLaneLabel = activeTurn ? formatTurnLaneLabel(activeTurn.lane) : 'Keeper 턴'
  const lastObserved = effectivePreview ? formatChatTime(effectivePreview.updated_at_unix) : null
  const snapshotLive = activeTurn !== null && row?.status === 'ok' && turnRead?.kind === 'value'
    && !turnRead.stale && turnRead !== invalidatedSnapshot
  const turnLive = observerConnected.value && (snapshotLive || matchedPreview?.live === true)
  const turnAnimating = turnLive && liveTurnTone !== 'bad'
  const progressLabel = turnLive
    ? (turnAnimating ? 'Working' : liveTurnDoing?.phrase ?? liveTurnActivity.label)
    : '마지막 확인'
  const snapshotAt = snapshot?.updatedAt
  const turnObservedAt = snapshotAt === undefined
    ? undefined : Math.max(snapshotAt, matchedPreview?.receivedAt ?? snapshotAt)
  const turnStartedAt = activeTurn && snapshotAt !== undefined
    ? (activeTurn.started_at_unix > 0 ? activeTurn.started_at_unix * 1000 : null)
    : null
  const activeTool = effectivePreview?.activity === 'tool' ? effectivePreview.last_tool : null
  const liveToolName = activeTool ?? effectivePreview?.last_tool ?? null
  const isLiveToolInFlight = turnAnimating && activeTool !== null
    && (snapshotLive || matchedPreview?.preview.activity === 'tool')
  // The last tool the turn observed is a call the model started, a call that
  // runs, or one that returned. With the list of open work its rows say which
  // call runs and where each stands, so the pill names only a tool no row
  // names: the one that returned. A server from before the list has the pill alone.
  const lastToolPill = liveToolName === null
    ? null
    : openWork === null
      ? `${isLiveToolInFlight ? '실행 중' : '최근 도구'} · ${liveToolName}`
      : hasOpenToolCall(openWork, liveToolName) ? null : `최근 도구 · ${liveToolName}`
  // Once the list of open work is read, the card says the turn in the
  // dashboard's words: a line for what no row names, the rows, and why an
  // attempt failed. The server's sentence says the same in English; it is
  // drawn only for a preview whose list was not sent or could not be read.
  const attemptFailed = effectivePreview?.activity === 'failed'
  const lastFailure = openWork !== null ? effectivePreview?.last_failure ?? null : null
  // The failure of the attempt in view is the line itself, in the tone of a
  // turn that stopped short. One that a later attempt has left behind is said
  // as such, below what that attempt has open, and is not colored: it is not
  // what happens now.
  const failureLine = lastFailure === null
    ? null
    : attemptFailed ? `${liveTurnActivity.label} · ${lastFailure}` : `앞선 시도 실패 · ${lastFailure}`
  const cardDoing = effectivePreview && openWork !== null && !(attemptFailed && failureLine !== null)
    ? turnDoingBesideRows(effectivePreview)
    : null
  const workedAt = lastWorked ? new Date(lastWorked.atUnix * 1000) : null

  const renderToolPreSection = (
    label: string,
    text: string,
    preKey: string,
    opts?: {
      readonly cachedRes?: ToolResultState
      readonly executionId?: string
    },
  ) => {
    const cachedRes = opts?.cachedRes
    const executionId = opts?.executionId
    const progressText = formatToolResultProgress(cachedRes)
    const isExpandedPre = expandedPreKeys[preKey] === true
    const isLong = isLongToolOutput(text)
    const markdown = opts && (cachedRes?.status !== 'loaded' || (cachedRes.eof && !cachedRes.isBinary))
      ? toolResultMarkdownPreview(text) : null
    const raw = html`<pre class=${isExpandedPre ? 'kp-block-pre kp-block-pre--expanded' : 'kp-block-pre'}>${text}</pre>`
    const showPager = Boolean(
      canAdminLocalChat
      && executionId
      && cachedRes?.status === 'loaded'
      && !cachedRes.eof
      && !cachedRes.isBinary,
    )
    return html`
      <div class="kp-block-subbar">
        <div class="kp-pill-row">
          <span class="kp-block-sublabel">
            ${label}${cachedRes?.status === 'loaded' && cachedRes.eof === false ? ' · 일부 표시' : ''}
          </span>
          ${progressText && html`
            <span class="kp-pill" data-tone=${cachedRes?.eof === false ? 'warn' : 'default'}>
              ${progressText}
            </span>
          `}
          ${cachedRes?.status === 'loaded' && cachedRes.isBinary && html`
            <span class="kp-pill">바이너리 · ${formatByteSize(cachedRes.totalBytes ?? cachedRes.recordedBytes ?? 0)}</span>
          `}
        </div>
        <div class="kp-block-subactions">
          <button
            type="button"
            class="btn-ghost kp-toggle-btn"
            onClick=${() => void handleCopyPre(preKey, text)}
          >
            ${copiedPreKey === preKey ? '복사됨' : '복사'}
          </button>
          ${isLong && html`
            <button
              type="button"
              class="btn-ghost kp-toggle-btn"
              onClick=${() => setExpandedPreKeys((prev) => ({ ...prev, [preKey]: !prev[preKey] }))}
            >
              ${isExpandedPre ? '축소' : '전체 높이'}
            </button>
          `}
        </div>
      </div>
      ${markdown === null ? raw : html`
        <${MarkdownContent} text=${markdown} />
        <details open=${isExpandedPre || undefined}>
          <summary>저장 참조</summary>
          ${raw}
        </details>
      `}
      ${showPager && html`
        <div class="kp-tool-result-pager" data-testid="tool-result-pager">
          <span class="kp-pill" data-tone="warn">
            ${cachedRes?.loadingMore
              ? `불러오는 중… (${progressText ?? ''})`
              : progressText ?? '일부 표시'}
          </span>
          <div class="kp-block-subactions">
            <button
              type="button"
              class="btn-ghost kp-toggle-btn"
              disabled=${cachedRes?.loadingMore === true}
              onClick=${() => void loadMoreToolResult(executionId!, 1)}
            >
              더 불러오기 (+16KB)
            </button>
            <button
              type="button"
              class="btn-ghost kp-toggle-btn"
              disabled=${cachedRes?.loadingMore === true}
              onClick=${() => void loadMoreToolResult(executionId!, TOOL_RESULT_MAX_PAGES_PER_BURST)}
            >
              끝까지 불러오기
            </button>
          </div>
        </div>
      `}
      ${canAdminLocalChat && executionId && cachedRes?.status === 'loaded' && cachedRes.loadMoreError && html`
        <div class="kp-tool-result-error" role="alert" data-testid="tool-result-load-more-error">
          <span>${cachedRes.loadMoreError}</span>
          <div class="kp-block-subactions">
            ${cachedRes.loadMoreConflict
              ? html`
                  <button
                    type="button"
                    class="btn-ghost kp-toggle-btn"
                    onClick=${() => void requestToolResult(executionId, true)}
                  >
                    처음부터 다시 불러오기
                  </button>
                `
              : html`
                  <button
                    type="button"
                    class="btn-ghost kp-toggle-btn"
                    onClick=${() => void loadMoreToolResult(executionId, 1)}
                  >
                    다시 시도
                  </button>
                  <button
                    type="button"
                    class="btn-ghost kp-toggle-btn"
                    onClick=${() => void requestToolResult(executionId, true)}
                  >
                    처음부터 다시 불러오기
                  </button>
                `}
          </div>
        </div>
      `}
    `
  }

  const renderToolResultStatus = (
    tb: ChatToolBlock,
    cachedRes: ToolResultState | undefined,
    displayArgs: string | undefined,
    displayResult: string | undefined,
    effectiveStatus: string | undefined,
    loadingLabel: string,
    hasInlineSummary: boolean,
  ) => html`
    ${!displayResult && cachedRes?.status === 'loaded' && html`
      <div class="kp-block-status">(빈 출력 · 0 B)</div>
    `}
    ${!displayResult && cachedRes?.status === 'loading' && html`
      <div class="kp-block-status">${loadingLabel}</div>
    `}
    ${!displayResult && cachedRes?.status === 'pending' && html`
      <div class="kp-block-status">
        도구 실행 중 — 결과 준비 대기 중…
        ${canAdminLocalChat && tb.executionId && html`
          ${' '}
          <button
            type="button"
            class="btn-ghost kp-toggle-btn"
            onClick=${() => void requestToolResult(tb.executionId!, true)}
          >
            다시 확인
          </button>
        `}
      </div>
    `}
    ${!displayResult && cachedRes?.status === 'unavailable' && html`
      <div class="kp-block-status">저장된 결과 없음 (${cachedRes.detail ?? 'unavailable'})</div>
    `}
    ${!displayResult && cachedRes?.status === 'error' && html`
      <div class="kp-block-status">
        결과 조회 실패 (${cachedRes.detail ?? 'error'})
        ${canAdminLocalChat && tb.executionId && html`
          ${' '}
          <button
            type="button"
            class="btn-ghost kp-toggle-btn"
            onClick=${() => void requestToolResult(tb.executionId!, true)}
          >
            ${cachedRes.sourceChanged ? '처음부터 다시 불러오기' : '다시 시도'}
          </button>
        `}
      </div>
    `}
    ${!displayResult && !cachedRes && tb.executionId && (canAdminLocalChat
      ? html`
          <div class="kp-block-status">
            <button
              type="button"
              class="btn-ghost kp-toggle-btn"
              onClick=${() => void requestToolResult(tb.executionId!, true)}
            >
              실행 결과 불러오기
            </button>
          </div>
        `
      : html`
          <div class="kp-block-status" data-testid="chat-tool-result-admin-locked" role="status">
            도구 실행 상세 결과 조회는 토큰 인증 관리자 전용입니다.
          </div>
        `)}
    ${!hasInlineSummary && !displayArgs && !displayResult && !cachedRes && !tb.executionId && html`
      <div class="kp-block-status">
        ${tb.progressLabel
          ?? (effectiveStatus === 'running'
            ? '도구 실행 중…'
            : effectiveStatus === 'awaiting_result'
              ? '도구 호출 완료 — 결과 대기 중…'
              : effectiveStatus === 'awaiting_approval'
                ? '운영자 승인 대기 중…'
                : '기록된 입력·결과가 없습니다.')}
      </div>
    `}
  `

  const renderToolCard = (tb: ChatToolBlock, idx: number, keyPrefix: string) => {
    const cachedRes = tb.executionId ? toolResultCache[tb.executionId] : undefined
    const displayArgs = tb.args ? prettyFormatPayload(tb.args) : undefined
    const displayResult = tb.result ?? (cachedRes?.status === 'loaded' ? cachedRes.displayContent : undefined)
    const effectiveStatus =
      cachedRes?.status === 'loaded'
        ? (cachedRes.isError ? 'error' : 'completed')
        : tb.status
    const statusMeta = toolStatusMeta(effectiveStatus)
    const delegateInfo = extractDelegateCardInfo({
      ...tb,
      args: displayArgs ?? tb.args,
      result: displayResult ?? tb.result,
    })
    const cardKey = `${keyPrefix}:tool:${tb.streamKey ?? idx}`
    const isExpanded =
      expandedCardKeys[cardKey]
      ?? (tb.executionId ? expandedCardKeys[`exec:${tb.executionId}`] : undefined)
      ?? (blockPrefs.tools === 'full')
    renderedOpenRef.current.set(cardKey, isExpanded)

    const handleToggle = (e: Event) => {
      const el = e.currentTarget as HTMLDetailsElement
      // Ignore programmatic `open` attribute sync events (sync in happy-dom / async in browsers)
      // so switching `Tools: summary -> full` never triggers an unbounded fetch storm.
      if (el.open === renderedOpenRef.current.get(cardKey)) return
      renderedOpenRef.current.set(cardKey, el.open)
      setCardExpanded(cardKey, el.open, tb.executionId)
      if (
        el.open
        && canUseSingleUserTokenAdmin(authSession.peek())
        && tb.executionId
        && !displayResult
        && (!cachedRes || cachedRes.status === 'pending' || cachedRes.status === 'error')
      ) {
        void requestToolResult(tb.executionId, true)
      }
    }

    if (delegateInfo) {
      const actionTitle =
        delegateInfo.kind === 'delegate'
          ? '위임'
          : delegateInfo.kind === 'delegate_status'
            ? '위임 조회'
            : '위임 취소'
      const targetSuffix =
        delegateInfo.targetKeepers.length > 1
          ? ` → @${delegateInfo.targetKeepers[0]} 외 ${delegateInfo.targetKeepers.length - 1}명`
          : delegateInfo.targetKeeper
            ? ` → @${delegateInfo.targetKeeper}`
            : ''
      const delStatus = delegateInfo.delegateState ?? tb.progressLabel ?? statusMeta.label
      const rawDelegatePreview =
        delegateInfo.prompt
        ?? (delegateInfo.operationCount > 1 ? `대상 ${delegateInfo.operationCount}건` : null)
        ?? delegateInfo.operationId
        ?? delStatus
      const preview = summarizeCompact(
        typeof rawDelegatePreview === 'string' && rawDelegatePreview.length > 512
          ? rawDelegatePreview.slice(0, 512)
          : rawDelegatePreview,
        90,
      )
      const hasInlineSummary = Boolean(delegateInfo.prompt || delegateInfo.operationId || delegateInfo.operationCount > 0)
      const rawKey = `${cardKey}:raw`
      const isRawExpanded = expandedCardKeys[rawKey] === true
      renderedOpenRef.current.set(rawKey, isRawExpanded)
      return html`
        <div
          key=${cardKey}
          class="kp-collapsible-shell kp-block-card kp-block-card--delegate"
          data-testid="chat-delegate-card"
        >
          <details
            class="kp-collapsible-details"
            open=${isExpanded}
            onToggle=${handleToggle}
          >
            <summary class="kp-block-summary">
              <span class="kp-pill" data-tone="brass">
                ${actionTitle}${targetSuffix}
              </span>
              <span class="kp-pill" data-tone=${statusMeta.tone}>
                ${delStatus}${tb.duration ? ` · ${tb.duration}` : ''}
              </span>
              <span class="kp-block-preview">${preview}</span>
            </summary>
            <div class="kp-block-content">
              ${delegateInfo.prompt && html`
                <div class="kp-block-sublabel">위임 요청 내용</div>
                <div class="kp-delegate-prompt">${delegateInfo.prompt}</div>
              `}
              <div class="kp-pill-row">
                ${delegateInfo.operationCount > 1 && html`
                  <span class="kp-pill">조회 대상 ${delegateInfo.operationCount}건</span>
                `}
                ${delegateInfo.operationId && html`
                  <span class="kp-pill">op: ${delegateInfo.operationId}</span>
                `}
                ${delegateInfo.artifactCount > 0 && html`
                  <span class="kp-pill">아티팩트 ${delegateInfo.artifactCount}개</span>
                `}
                ${delegateInfo.targetTurnAgeSec !== null && html`
                  <span class="kp-pill" data-tone="warn">상대 턴 경과 ${formatElapsedCompact(delegateInfo.targetTurnAgeSec)}</span>
                `}
              </div>
              ${(displayArgs || displayResult) && html`
                <details
                  key=${rawKey}
                  class="kp-sub-details"
                  open=${isRawExpanded}
                  onToggle=${(e: Event) => {
                    const nextOpen = (e.currentTarget as HTMLDetailsElement).open
                    if (nextOpen === renderedOpenRef.current.get(rawKey)) return
                    renderedOpenRef.current.set(rawKey, nextOpen)
                    setCardExpanded(rawKey, nextOpen)
                  }}
                >
                  <summary class="kp-sub-summary">원본 입출력 (JSON)</summary>
                  <div class="kp-block-content">
                    ${displayArgs && renderToolPreSection('입력 (Args)', displayArgs, `${cardKey}:args`)}
                    ${displayResult && renderToolPreSection('결과 (Result)', displayResult, `${cardKey}:result`, {
                      cachedRes,
                      executionId: tb.executionId,
                    })}
                  </div>
                </details>
              `}
              ${renderToolResultStatus(
                tb,
                cachedRes,
                displayArgs,
                displayResult,
                effectiveStatus,
                '위임 응답 불러오는 중…',
                hasInlineSummary,
              )}
            </div>
          </details>
          ${delegateInfo.targetKeepers.length > 0 && props.onSelectKeeper && html`
            <div class="kp-collapsible-actions">
              ${delegateInfo.targetKeepers.map((target) => html`
                <button
                  key=${target}
                  type="button"
                  class="btn-ghost kp-toggle-btn kp-delegate-jump"
                  aria-label=${`${target} Keeper 대화로 이동`}
                  onClick=${() => props.onSelectKeeper?.(target)}
                >
                  @${target} ↗
                </button>
              `)}
            </div>
          `}
        </div>
      `
    }

    const rawPreviewSource = displayArgs ?? displayResult ?? tb.progressLabel ?? statusMeta.label
    const previewText = summarizeCompact(
      typeof rawPreviewSource === 'string' && rawPreviewSource.length > 512
        ? rawPreviewSource.slice(0, 512)
        : rawPreviewSource,
      90,
    )
    return html`
      <details
        key=${cardKey}
        class="kp-block-card kp-block-card--tool"
        data-testid="chat-tool-card"
        open=${isExpanded}
        onToggle=${handleToggle}
      >
        <summary class="kp-block-summary">
          <span class="kp-pill" data-tone=${statusMeta.tone}>도구 · ${tb.name}</span>
          <span class="kp-pill" data-tone=${statusMeta.tone}>
            ${tb.progressLabel ?? statusMeta.label}${tb.duration ? ` · ${tb.duration}` : ''}
          </span>
          <span class="kp-block-preview">${previewText}</span>
        </summary>
        <div class="kp-block-content">
          ${displayArgs && renderToolPreSection('입력 (Args)', displayArgs, `${cardKey}:args`)}
          ${displayResult && renderToolPreSection('결과 (Result)', displayResult, `${cardKey}:result`, {
            cachedRes,
            executionId: tb.executionId,
          })}
          ${tb.attachments && tb.attachments.length > 0 && html`
            <${AttachmentGallery}
              attachments=${tb.attachments}
              workspaceEpoch=${currentSessionEpoch()}
              compact=${true}
            />
          `}
          ${renderToolResultStatus(
            tb,
            cachedRes,
            displayArgs,
            displayResult,
            effectiveStatus,
            '결과 불러오는 중…',
            false,
          )}
        </div>
      </details>
    `
  }

  const lastVisible = visibleEntries[visibleEntries.length - 1]?.msg
  const liveSig = showLiveTurnCard
    ? `live:${effectivePreview?.revision ?? 0}:${effectivePreview?.text_tail.length ?? 0}:${liveToolName ?? ''}`
    : ''
  const mediaSig = [
    ...(lastVisible?.retainedImages?.map((image) => image.path) ?? []),
    ...(lastVisible?.attachments?.map((att) => att.attachment_id || att.url) ?? []),
  ].join(',')
  const tailSig = lastVisible
    ? `${visibleEntries.length}:${lastVisible.id}:${lastVisible.content.length}:${lastVisible.thinking?.length ?? 0}:${lastVisible.toolCalls?.length ?? 0}:${lastVisible.deliveryState ?? ''}:${lastVisible.errorDetail ?? ''}:${mediaSig}:${liveSig}`
    : `${visibleEntries.length}:empty:${liveSig}`

  useLayoutEffect(() => {
    const el = chatListRef.current
    if (!el) return

    // Preserve exact viewport anchor when older history pages are prepended
    const anchor = pendingPrependAnchorRef.current
    if (anchor) {
      pendingPrependAnchorRef.current = null
      const delta = el.scrollHeight - anchor.prevScrollHeight
      el.scrollTop = anchor.prevScrollTop + Math.max(0, delta)
      prevTailSigRef.current = tailSig
      return
    }

    const tailChanged = tailSig !== prevTailSigRef.current
    prevTailSigRef.current = tailSig

    if (forceScrollBottomRef.current) {
      if (visibleEntries.length > 0 || !(loadingHistory || isSwitchingKeeper)) {
        forceScrollBottomRef.current = false
        scrollToBottom('auto')
      }
      return
    }

    if (!tailChanged) return

    if (stickToBottomRef.current) {
      scrollToBottom('auto')
    } else if (visibleEntries.length > 0) {
      setUnseenBelowCount((c) => c + 1)
    }
  }, [tailSig, loadingHistory, isSwitchingKeeper, visibleEntries.length, scrollToBottom])

  return html`
    <div class="kp-chat-shell" data-companion-open=${companionOpen ? 'true' : 'false'}>
      <div class="kp-chat-main">
        <div class="kp-chat-toolbar">
          <div class="kp-pill-row">
            <span class="kp-pill" data-tone="info">Origin_bare · AG-UI SSE</span>
            <${PopoverMenu}
              triggerLabel=${`표시 ▾`}
              triggerClassName="btn-ghost kp-toggle-btn"
              triggerTestId="chat-display-menu"
              popoverTestId="chat-display-popover"
              ariaLabel="채팅 블록 표시 설정"
              triggerTitle=${`추론: ${thinkingModeLabel(blockPrefs.thinking)} · 도구: ${toolsModeLabel(blockPrefs.tools)} · 메모리·내부: ${internalModeLabel(blockPrefs.internal)}`}
              closeOnSelect=${false}
              items=${[
                {
                  id: 'thinking',
                  testId: 'chat-toggle-thinking',
                  label: `추론: ${thinkingModeLabel(blockPrefs.thinking)}`,
                  shortcut: 'Alt+T',
                  onSelect: () => updateBlockPrefs((cur) => ({ ...cur, thinking: nextThinkingMode(cur.thinking) })),
                },
                {
                  id: 'tools',
                  testId: 'chat-toggle-tools',
                  label: `도구: ${toolsModeLabel(blockPrefs.tools)}`,
                  onSelect: () => updateBlockPrefs((cur) => ({ ...cur, tools: nextToolsMode(cur.tools) })),
                },
                {
                  id: 'internal',
                  testId: 'chat-toggle-internal',
                  label: `메모리·내부: ${internalModeLabel(blockPrefs.internal)}${hiddenInternalCount > 0 ? ` (${hiddenInternalCount})` : ''}`,
                  onSelect: () => updateBlockPrefs((cur) => ({ ...cur, internal: nextInternalMode(cur.internal) })),
                },
              ]}
            />
            ${hasMore && html`
              <button type="button" class="btn-ghost" disabled=${loadingHistory} onClick=${() => void handleLoadEarlier()}>
                이전 대화 불러오기
              </button>
            `}
          </div>
          <div class="kp-pill-row">
            <button
              type="button"
              class="btn-ghost"
              aria-pressed=${btwOpen ? 'true' : 'false'}
              onClick=${() => setBtwOpen((v) => !v)}
            >
              /btw 사이드 질의
            </button>
            <button
              type="button"
              class="btn-ghost"
              aria-pressed=${companionOpen ? 'true' : 'false'}
              onClick=${() => setCompanionOpen((v) => !v)}
            >
              ${companionOpen ? 'Debug 닫기 (⌘.)' : 'Debug 열기 (⌘.)'}
            </button>
          </div>
        </div>

        ${historyError && html`<div class="ap-error" role="alert">${historyError}</div>`}

        <div class="kp-chat-stage">
          <div
            ref=${chatListRef}
            class="kp-chat-list"
            role="log"
            aria-label="Keeper 대화 기록"
            onScroll=${handleChatScroll}
          >
            <div class="kp-chat-feed" ref=${chatFeedRef}>
            ${(loadingHistory || isSwitchingKeeper) && scopedMessages.length === 0
              ? html`<div class="kp-empty">대화 기록 불러오는 중…</div>`
              : displayItems.length === 0 && !showLiveTurnCard
                ? html`<div class="kp-empty">${scopedMessages.length > 0 ? '현재 블록 필터에 표시할 메시지가 없습니다.' : `${keeper.name}과(와) 대화를 시작하세요.`}</div>`
                : displayItems.map((item) => {
                    if (item.kind === 'tool_group') {
                      if (item.toolBlocks.length === 1) {
                        const singleEntry = item.entries[0]!
                        return html`
                          <div key=${item.id} class="kp-activity-single" data-testid="chat-tool-single">
                            ${renderToolCard(singleEntry.blocks.toolBlocks[0]!, 0, singleEntry.msg.id)}
                          </div>
                        `
                      }
                      const isGroupExpanded = expandedCardKeys[item.id] ?? (blockPrefs.tools === 'full')
                      renderedOpenRef.current.set(item.id, isGroupExpanded)
                      return html`
                        <div
                          key=${item.id}
                          class="kp-collapsible-shell kp-activity-group"
                          data-testid="chat-tool-group"
                        >
                          <details
                            class="kp-collapsible-details"
                            open=${isGroupExpanded}
                            onToggle=${(e: Event) => {
                              const nextOpen = (e.currentTarget as HTMLDetailsElement).open
                              if (nextOpen === renderedOpenRef.current.get(item.id)) return
                              renderedOpenRef.current.set(item.id, nextOpen)
                              setCardExpanded(item.id, nextOpen)
                            }}
                          >
                            <summary class="kp-activity-group-summary">
                              <span class="kp-pill" data-tone="info">도구 활동 · ${item.toolBlocks.length}건</span>
                              <span class="kp-block-preview">${item.toolSummary}</span>
                            </summary>
                            <div class="kp-hierarchy-rail">
                              ${item.entries.flatMap((entry) =>
                                entry.blocks.toolBlocks.map((tb, tbIdx) => renderToolCard(tb, tbIdx, entry.msg.id)),
                              )}
                            </div>
                          </details>
                          ${item.delegateTargets.length > 0 && props.onSelectKeeper && html`
                            <div class="kp-collapsible-actions">
                              ${item.delegateTargets.map((target) => html`
                                <button
                                  key=${target}
                                  type="button"
                                  class="btn-ghost kp-toggle-btn kp-delegate-jump"
                                  aria-label=${`${target} Keeper 대화로 이동`}
                                  onClick=${() => props.onSelectKeeper?.(target)}
                                >
                                  @${target} ↗
                                </button>
                              `)}
                            </div>
                          `}
                        </div>
                      `
                    }

                    const { msg, blocks } = item.entry
                    const timeLabel = formatChatTime(msg.ts)
                    const showThinking = Boolean(blocks.thinkingText && blockPrefs.thinking !== 'hidden')
                    const showTools = blocks.toolBlocks.length > 0 && blockPrefs.tools !== 'hidden'
                    const showMemory = blocks.memoryItems.length > 0 && blockPrefs.internal === 'shown'
                    const showAutonomous = blocks.autonomousSummary !== null && blockPrefs.internal === 'shown'
                    const hasTraceRail = showThinking || showTools || showMemory || showAutonomous
                    const hasInFlightTool = blocks.toolBlocks.some(
                      (tb) => tb.status === 'running' || tb.status === 'awaiting_result' || tb.status === 'awaiting_approval',
                    )
                    const thinkingKey = `${msg.id}:thinking`
                    const isThinkingOpen = expandedThinkingKeys[thinkingKey] ?? (blockPrefs.thinking === 'expanded')
                    renderedOpenRef.current.set(thinkingKey, isThinkingOpen)
                    const turnGroupKey = `turn-tools:${msg.id}`
                    if (hasInFlightTool) autoOpenedGroupsRef.current.add(turnGroupKey)
                    const isTurnGroupOpen =
                      expandedCardKeys[turnGroupKey]
                      ?? (blockPrefs.tools === 'full' || autoOpenedGroupsRef.current.has(turnGroupKey))
                    renderedOpenRef.current.set(turnGroupKey, isTurnGroupOpen)

                    return html`
                      <article key=${msg.id} class="kp-msg" data-role=${msg.role}>
                        <div class="kp-msg-head">
                          <span>
                            ${formatChatSpeakerLabel(
                              msg,
                              keeper.name,
                              blocks.autonomousSummary,
                              blocks.memoryItems.length > 0 && blocks.bodyText.length === 0,
                            )}
                          </span>
                          <div class="kp-pill-row">
                            ${timeLabel && html`<time class="kp-msg-time tnum">${timeLabel}</time>`}
                            ${msg.surface && msg.surface !== 'chat' && msg.surface !== 'dashboard' && html`
                              <span class="kp-pill" data-tone="info">${msg.surface}</span>
                            `}
                            ${msg.runtimeAttempt && runtimeAttemptLabel(msg.runtimeAttempt) && html`
                              <span class="kp-pill" data-tone="info" data-testid="chat-runtime-attempt">
                                ${runtimeAttemptLabel(msg.runtimeAttempt)}
                              </span>
                            `}
                            ${msg.deliveryState && html`
                              <span class="kp-pill" data-tone=${deliveryBadgeTone(msg.deliveryState)}>
                                ${msg.deliveryState}
                              </span>
                            `}
                            ${discordOperator && msg.discordReplyOrigin && html`
                              <button type="button" class="btn-ghost"
                                aria-expanded=${discordReplyId === msg.id ? 'true' : 'false'}
                                onClick=${(event: MouseEvent) => {
                                  discordReplyTrigger.current = event.currentTarget as HTMLButtonElement
                                  setDiscordReplyId(id => id === msg.id ? null : msg.id)
                                }}>
                                Discord 답장
                              </button>
                            `}
                            ${canAdminLocalChat && msg.cutStream && msg.operationId && html`
                              <button
                                type="button"
                                class="btn-ghost"
                                onClick=${() => void handleRecoverCut(msg.id, msg.operationId!)}
                              >
                                저널 복구
                              </button>
                            `}
                          </div>
                        </div>

                        ${hasTraceRail && html`
                          <div class="kp-turn-trace" data-testid="chat-turn-trace">
                            ${showThinking && html`
                              <details
                                key=${thinkingKey}
                                class="kp-block-card kp-msg-thinking"
                                data-testid="chat-thinking-card"
                                open=${isThinkingOpen}
                                onToggle=${(e: Event) => {
                                  const nextOpen = (e.currentTarget as HTMLDetailsElement).open
                                  if (nextOpen === renderedOpenRef.current.get(thinkingKey)) return
                                  renderedOpenRef.current.set(thinkingKey, nextOpen)
                                  setExpandedThinkingKeys((prev) =>
                                    prev[thinkingKey] === nextOpen ? prev : { ...prev, [thinkingKey]: nextOpen },
                                  )
                                }}
                              >
                                <summary class="kp-block-summary">
                                  <span>추론 (Thinking)</span>
                                  <span class="kp-block-preview">${summarizeCompact(blocks.thinkingText, 80)}</span>
                                </summary>
                                <${MarkdownContent} class="kp-block-content" text=${blocks.thinkingText} streaming=${msg.deliveryState === 'Streaming'} />
                              </details>
                            `}

                            ${showTools && (blocks.toolBlocks.length === 1
                              ? html`
                                  <div class="kp-block-stack">
                                    ${renderToolCard(blocks.toolBlocks[0]!, 0, msg.id)}
                                  </div>
                                `
                              : html`
                                  <details
                                    key=${turnGroupKey}
                                    class="kp-tool-subgroup"
                                    data-testid="chat-turn-tool-group"
                                    open=${isTurnGroupOpen}
                                    onToggle=${(e: Event) => {
                                      const nextOpen = (e.currentTarget as HTMLDetailsElement).open
                                      if (nextOpen === renderedOpenRef.current.get(turnGroupKey)) return
                                      renderedOpenRef.current.set(turnGroupKey, nextOpen)
                                      setCardExpanded(turnGroupKey, nextOpen)
                                    }}
                                  >
                                    <summary class="kp-block-summary">
                                      <span class="kp-pill" data-tone=${hasInFlightTool ? 'brass' : 'info'}>
                                        도구 실행 · ${blocks.toolBlocks.length}건
                                      </span>
                                      ${hasInFlightTool && html`
                                        <span class="kp-pill" data-tone="brass">진행 중</span>
                                      `}
                                      <span class="kp-block-preview">${summarizeToolHistogram(blocks.toolBlocks)}</span>
                                    </summary>
                                    <div class="kp-hierarchy-rail">
                                      ${blocks.toolBlocks.map((tb, idx) => renderToolCard(tb, idx, msg.id))}
                                    </div>
                                  </details>
                                `)}

                            ${showMemory && html`
                              <details key=${`${msg.id}:memory`} class="kp-block-card kp-block-card--memory" data-testid="chat-memory-card">
                                <summary class="kp-block-summary">
                                  <span class="kp-pill" data-tone="brass">메모리 회상 (${blocks.memoryItems.length})</span>
                                  <span class="kp-block-preview">${summarizeCompact(blocks.memoryItems[0], 90)}</span>
                                </summary>
                                <ul class="kp-block-list">
                                  ${blocks.memoryItems.map((item, idx) => html`<li key=${idx}><${MarkdownContent} text=${item} /></li>`)}
                                </ul>
                              </details>
                            `}

                            ${showAutonomous && html`
                              <details key=${`${msg.id}:autonomous`} class="kp-block-card kp-block-card--auto" data-testid="chat-autonomous-card">
                                <summary class="kp-block-summary">
                                  <span class="kp-pill" data-tone="warn">자율 턴 (Autonomous)</span>
                                  <span class="kp-block-preview">${blocks.autonomousSummary}</span>
                                </summary>
                                ${blocks.autonomousDetails && html`
                                  <pre class="kp-block-pre">${blocks.autonomousDetails}</pre>
                                `}
                              </details>
                            `}
                          </div>
                        `}

                        ${(blocks.bodyText || msg.deliveryState === 'Streaming' || msg.deliveryState === 'Pending_processing') && html`
                          ${blocks.bodyText
                            ? html`<${MarkdownContent} class="kp-msg-body" text=${blocks.bodyText} streaming=${msg.deliveryState === 'Streaming'} />`
                            : (!showLiveTurnCard && openWork !== null && openWork.length > 0)
                              ? null
                              : html`<div class="kp-msg-body">${msg.deliveryState === 'Pending_processing' ? '요청 처리 준비 중…' : '응답 생성 중…'}</div>`}
                          ${!showLiveTurnCard && (msg.deliveryState === 'Streaming' || msg.deliveryState === 'Pending_processing') && openWork !== null && openWork.length > 0 && html`
                            <${OpenWorkRows} activities=${openWork} live=${turnAnimating} />
                          `}
                        `}
                        ${(() => {
                          const displayAttachments = entryDisplayAttachments(msg)
                          if (displayAttachments.length === 0) return null
                          const attEpoch = msg.retainedImages?.[0]?.workspaceEpoch ?? currentSessionEpoch()
                          return html`
                            <${AttachmentGallery}
                              attachments=${displayAttachments}
                              workspaceEpoch=${attEpoch}
                            />
                          `
                        })()}
                        ${msg.providerRetry && html`
                          <div class="kp-stream-notice" data-kind="retry" role="status">
                            ${providerRetryLabel(msg.providerRetry)}
                          </div>
                        `}
                        ${msg.streamNotices?.map((notice, index) => html`
                          <div class="kp-stream-notice" data-kind=${notice.kind} key=${`notice:${index}`}
                            role=${notice.kind === 'protocol_error' ? 'alert' : 'status'}>
                            <strong>${streamNoticePrefix(notice.kind)}</strong> ${notice.text}
                          </div>
                        `)}
                        ${msg.errorDetail && html`<div class="ap-error">${msg.errorDetail}</div>`}
                        ${discordOperator && msg.discordReplyOrigin && discordReplyId === msg.id && html`
                          <${DiscordReplyPanel}
                            key=${JSON.stringify([discordOperator, msg.id])}
                            target=${{ keeperName: keeper.name, chatId: msg.id, origin: msg.discordReplyOrigin }}
                            authority=${discordOperator}
                            onClose=${() => {
                              setDiscordReplyId(null)
                              discordReplyTrigger.current?.focus()
                            }} />
                        `}
                      </article>
                    `
                  })}

            ${showLiveTurnCard && html`
              <section class="kp-live-turn-card" data-testid="chat-live-turn-card">
                <div class="kp-msg-head">
                  <div class="kp-pill-row">
                    <span class="kp-pill" data-tone="brass" title=${effectivePreview?.status_text || undefined}>${liveTurnLaneLabel}</span>
                    ${activeTurn?.turn_ref && html`<span class="kp-pill">${activeTurn.turn_ref}</span>`}
                  </div>
                  <div class="kp-pill-row">
                    ${lastObserved && html`<span class="kp-pill">마지막 관측 ${lastObserved}</span>`}
                  </div>
                </div>
                <div class="kp-hierarchy-rail">
                  ${lastToolPill && html`
                    <div class="kp-pill-row">
                      <span class="kp-pill" data-tone="info">${lastToolPill}</span>
                    </div>
                  `}
                  ${openWork === null && effectivePreview?.status_text && html`
                    <div class="kp-live-turn-status">${effectivePreview.status_text}</div>
                  `}
                  ${cardDoing && html`
                    <div class="kp-live-turn-status" data-testid="chat-turn-doing" data-tone=${cardDoing.tone}>${cardDoing.phrase}</div>
                  `}
                  ${openWork !== null && openWork.length > 0 && html`
                    <${OpenWorkRows} activities=${openWork} live=${turnAnimating} />
                  `}
                  ${failureLine && html`
                    <div class="kp-live-turn-status" data-testid="chat-turn-failure" data-tone=${attemptFailed ? 'bad' : undefined}>${failureLine}</div>
                  `}
                  ${turnWorkContext && (turnWorkContext.start_reasons.length > 0 || turnWorkContext.task_id) && html`
                    <div class="kp-live-turn-status" data-testid="chat-turn-work-context">
                      ${turnWorkContext.start_reasons.length > 0
                        && `시작 계기: ${turnWorkContext.start_reasons.map(startReasonLabel).join(' · ')}`}
                      ${turnWorkContext.start_reasons.length > 0 && turnWorkContext.task_id && ' · '}
                      ${turnWorkContext.task_id && `시작 시 Task: ${turnWorkContext.task_id}`}
                    </div>
                  `}
                  ${effectivePreview?.text_tail && html`
                    <div class="kp-live-turn-tail">… ${effectivePreview.text_tail}</div>
                  `}
                </div>
              </section>
            `}
            </div>
          </div>
          ${!isNearBottom && (visibleEntries.length > 0 || showLiveTurnCard) && html`
            <button
              type="button"
              class="kp-scroll-bottom-btn"
              data-testid="chat-scroll-bottom"
              data-has-unseen=${unseenBelowCount > 0 ? 'true' : 'false'}
              onClick=${() => scrollToBottom('smooth')}
            >
              ${unseenBelowCount > 0 ? '↓ 새 응답 보기' : '↓ 맨 아래로'}
            </button>
          `}
        </div>

        ${waitingInventory && waitingInventory.rows.length > 0 && html`
          <${KeeperWaitingStrip} inventory=${waitingInventory} nowUnix=${Date.now() / 1000} />
        `}

        ${(queuedOps.length > 0 || !queue || queue.kind !== 'ready') && html`
          <div class="kp-queue-strip" aria-label="대기 중인 큐 작업">
            <div class="kp-queue-row">
              <span class="kp-kv-k">
                ${queuedOps.length ? `대기열 (${queuedOps.length})` : '대기열'}${queue?.kind === 'ready' && queue.refreshing ? ' · 갱신 중…' : ''}
              </span>
              <button type="button" class="btn-ghost" aria-label="대기열 새로고침"
                onClick=${() => retryQueueRef.current()}>새로고침</button>
            </div>
            ${(!queue || queue.kind === 'loading') && html`<div role="status">대기열 조회 중…</div>`}
            ${queue?.kind === 'error' && html`
              <div role="status" title=${queue.message}>
                ${queuedOps.length > 0 ? '이전에 조회한 대기열입니다.' : '대기열을 불러오지 못했습니다.'}
              </div>
            `}
            <div class="kp-queue-rows">
              ${queuedOps.map((op) => {
                const queueBusy = queue?.kind !== 'ready' || queue.refreshing === true
                return html`
                  <div key=${op.operationId} class="kp-queue-row">
                    <span class="kp-roster-name">${op.message || op.operationId}</span>
                    <div class="kp-pill-row">
                      ${canAdminLocalChat && html`
                        <button type="button" class="btn-ghost" disabled=${queueBusy}
                          onClick=${() => void updateQueueOperation(op.operationId, runQueuedChatOperationNext)}>
                          지금 실행
                        </button>
                      `}
                      <button type="button" class="btn-ghost" disabled=${queueBusy}
                        onClick=${() => void updateQueueOperation(op.operationId, moveQueuedChatOperationToEndApi)}>
                        뒤로
                      </button>
                      <button type="button" class="kp-btn-danger" disabled=${queueBusy}
                        onClick=${() => void updateQueueOperation(op.operationId, cancelQueuedChatOperation)}>
                        취소
                      </button>
                    </div>
                  </div>
                `
              })}
            </div>
          </div>
        `}

        ${btwOpen && html`
          <section class="kp-btw-box" aria-label="/btw 사이드 질의">
            <div class="kp-card-head">
              <h3>/btw Ephemeral Side-Query</h3>
              <button type="button" class="btn-ghost" onClick=${() => setBtwOpen(false)}>닫기</button>
            </div>
            <div class="kp-lifecycle-bar">
              <input
                type="text"
                class="kp-input"
                placeholder="임시 사이드 질문을 입력하세요…"
                value=${btwInput}
                onInput=${(e: Event) => setBtwInput((e.currentTarget as HTMLInputElement).value)}
                onKeyDown=${(e: KeyboardEvent) => {
                  if (e.isComposing || e.keyCode === 229) return
                  if (e.key === 'Escape') {
                    e.preventDefault()
                    e.stopPropagation()
                    setBtwOpen(false)
                    return
                  }
                  if (e.key === 'Enter') {
                    e.preventDefault()
                    if (btw.status === 'streaming' || !btwInput.trim()) return
                    const q = btwInput
                    setBtwInput('')
                    void runBtwQuery(q)
                  }
                }}
              />
              <button
                type="button"
                class="btn-primary"
                disabled=${btw.status === 'streaming'}
                onClick=${() => {
                  const q = btwInput
                  setBtwInput('')
                  void runBtwQuery(q)
                }}
              >
                질의
              </button>
            </div>
            ${btw.status !== 'idle' && html`
              <div class="kp-msg-body">
                <strong>Q:</strong>
                <${MarkdownContent} text=${btw.prompt} />
                ${btw.reply
                  ? html`<${MarkdownContent} text=${btw.reply} streaming=${btw.status === 'streaming'} />`
                  : btw.status === 'streaming' && html`<div>응답 수신 중…</div>`}
                ${btw.error && html`<div class="ap-error">${btw.error}</div>`}
              </div>
            `}
          </section>
        `}

        <!-- Hermes-style Composer Footer -->
        <${AttachmentComposer}
          className="kp-composer"
          items=${composerAttachments}
          onChange=${setComposerAttachments}
          showTrigger=${false}
          pickerRef=${openAttachmentPickerRef}
          onError=${(message: string) => setHistoryError(message)}
        >
          ${(hasTurnObservation || lastWorked) && html`
            <div class="kp-turn-progress">
              ${hasTurnObservation && html`
                <div class="kp-turn-progress-active" data-tone=${liveTurnTone} data-live=${turnLive ? 'true' : 'false'}>
                  ${turnAnimating && html`<span class="kp-live-dot" aria-hidden="true"></span>`}
                  <span class="kp-turn-progress-line">
                    <span role="status">
                      <strong>${progressLabel}</strong>
                      ${liveTurnDoing && (!turnLive || turnAnimating) && html`<span> · ${liveTurnDoing.phrase}</span>`}
                    </span>
                    ${liveTurnDoing && liveTurnDoing.sinceUnix !== null && turnAnimating && html`
                      <span> · </span><${OpenWorkSince} sinceUnix=${liveTurnDoing.sinceUnix} />
                    `}
                    <span> · ${liveTurnLaneLabel}</span>
                    ${turnStartedAt !== null && turnObservedAt !== undefined && html`
                      <span> </span><${KeeperTurnElapsed} key=${activeTurn?.owner_key ?? activeTurn?.turn_ref ?? activeTurn?.started_at_unix} startedAt=${turnStartedAt} observedAt=${turnObservedAt} live=${turnAnimating} />
                    `}
                  </span>
                </div>
              `}
              ${lastWorked && workedAt && html`
                <span class="kp-turn-worked" role="status">
                  <span aria-hidden="true">✓ </span><strong>Worked</strong>
                  ${` · ${formatElapsedCompact(lastWorked.elapsedMs / 1000)} · 최근 성공 `}
                  <time datetime=${workedAt.toISOString()} title=${workedAt.toLocaleString()}>${formatChatTime(lastWorked.atUnix)}</time>
                </span>
              `}
            </div>
          `}

          <textarea
            ref=${composerRef}
            class="kp-textarea"
            rows=${3}
            placeholder=${`${keeper.name}에게 메시지 전송 (Enter: Queue · ⌘↵: Steer · 이미지 붙여넣기/드롭 · /btw <질문>)`}
            aria-label="Keeper 채팅 입력"
            value=${draft}
            onInput=${(e: Event) => setDraft((e.currentTarget as HTMLTextAreaElement).value)}
            onKeyDown=${handleComposerKeyDown}
          />

          <input
            ref=${voiceInputRef}
            type="file"
            accept="audio/*"
            class="kp-hidden-input"
            onChange=${(e: Event) => void handleVoiceFile(e)}
          />

          <div class="kp-composer-footer">
            <div class="kp-composer-meta">
              <!-- Circular SVG Context Ring % (zero inline HTML style) -->
              <span class="kp-ctx-ring" title=${formatContextDetail(keeper).tooltip}>
                <svg class="kp-ring-svg" viewBox="0 0 22 22" aria-hidden="true">
                  <circle class="kp-ring-track" cx="11" cy="11" r="8.5" />
                  <circle
                    class="kp-ring-fill"
                    data-tone=${ringTone}
                    cx="11"
                    cy="11"
                    r="8.5"
                    stroke-dasharray=${RING_CIRCUMFERENCE.toFixed(2)}
                    stroke-dashoffset=${ringOffset.toFixed(2)}
                  />
                </svg>
                <span>Ctx ${ctxObs.kind === 'value' ? formatContextDetail(keeper).label : formatObserved(ctxObs, (v) => `${v}%`)}</span>
              </span>

              <button
                type="button"
                class="btn-ghost"
                onClick=${() => openAttachmentPickerRef.current?.()}
              >
                첨부
              </button>
              ${canAdminLocalChat && html`
                <button
                  type="button"
                  class="btn-ghost"
                  disabled=${voiceBusy}
                  onClick=${() => voiceInputRef.current?.click()}
                >
                  ${voiceBusy ? 'STT 인식 중…' : '음성 STT'}
                </button>
              `}
            </div>

            <div class="kp-composer-actions">
              <button
                type="button"
                class="btn-ghost"
                disabled=${followUpSubmitting || hasUploadingAttachments(composerAttachments) || hasFailedAttachments(composerAttachments)}
                onClick=${() => void submitMessage('queue')}
              >
                Queue ↵
              </button>
              <button
                type="button"
                class="btn-primary"
                disabled=${followUpSubmitting || hasUploadingAttachments(composerAttachments) || hasFailedAttachments(composerAttachments)}
                onClick=${() => void submitMessage('steer')}
              >
                Steer ⌘↵
              </button>
            </div>
          </div>
        <//>
      </div>

      ${companionOpen && html`
        <${ErrorBoundary} label="Keeper Debug" fallback=${() => html`
          <aside class="kp-companion" aria-label="Debug Companion (⌘.)">
            <div class="kp-companion-head">
              <span role="alert">Debug 패널을 불러오지 못했습니다.</span>
              <button type="button" class="btn-ghost" onClick=${() => setCompanionOpen(false)}>닫기</button>
            </div>
          </aside>
        `}>
          <${Suspense} fallback=${html`
            <aside class="kp-companion" role="status">
              <div class="kp-companion-head">Debug 불러오는 중…</div>
            </aside>
          `}>
            <${LazyKeeperDebugCompanion}
              keeperName=${keeper.name}
              onClose=${() => setCompanionOpen(false)}
              onInspect=${props.onInspect}
              onMutated=${props.onMutated}
            />
          </${Suspense}>
        </${ErrorBoundary}>
      `}
    </div>
  `
}
